def _argf(flag, default):
    if flag in sys.argv:
        try: _v = float(sys.argv[sys.argv.index(flag)+1])
        except Exception: print(f"bad {flag}"); sys.exit(1)
        if not math.isfinite(_v):
            # v3.7.12 (P4): nan/inf silently poison thresholds (max(NaN,x)
            # comparisons fail open) — refuse before any MT5/state access
            print(f"*** {flag} must be a FINITE number (got "
                  f"{sys.argv[sys.argv.index(flag)+1]!r}) — refusing to start")
            sys.exit(1)
        return _v
    return default
def _args(flag, default):
    if flag in sys.argv:
        try: return sys.argv[sys.argv.index(flag)+1]
        except Exception: print(f"bad {flag}"); sys.exit(1)
    return default

