def _fin_num(x):
    """v3.7.1 (R19-F1): shared finiteness test — a numeric, non-bool,
    finite value. The v3.7.0 warm anchor grew this guard (as a local _fin);
    the COLD reconstruction path was left on raw arithmetic, so a NaN
    balance or one NaN deal field on a mid-day restart cached a NaN anchor
    and every breaker/daily comparison went silently False for the rest of
    the day (round-19 F-1, repro-verified; pre-existing since v3.6.9)."""
    return (isinstance(x, (int, float)) and not isinstance(x, bool)
            and math.isfinite(x))

def _risk_levels(anc, sb):
    """v3.7.5 (F11): the day's hard lines, printed once per day so the
    operator can see what the account must not touch."""
    binding = _economic_binding()
    breaker_bps = (binding.get("breaker_bps")
                   if isinstance(binding, dict) else None)
    breaker = _translated_loss_line(anc, breaker_bps)
    daily = _translated_loss_line(anc, 500)
    floor = _translated_floor_line()
    if not all(_finite_num(value) for value in (breaker, daily, floor)):
        # Presentation-only fallback before lifecycle binding in offline
        # diagnostics. Live rail callers require the schema-8 authority.
        breaker = anc - sb * BREAKER_PCT / 100.0
        daily = anc - sb * 0.05
        floor = sb * 0.90
    out = (f"breaker flat <= {breaker:,.2f} | "
           f"daily -5% <= {daily:,.2f} | "
           f"floor <= {floor:,.2f}")
    try:
        target_line = _target_display_value(fallback_start=sb)
        if target_line is not None:
            out += f" | target >= {target_line:,.2f}"
    except Exception:
        pass
    return out


_LOG_MAX_BYTES = 5 * 1024 * 1024
_LOG_MAX_SEGMENTS = 4
_LOG_KEEP_DAYS = 14
_LOG_CLEANED_DAY = [None]
_LOG_WRITE_WARNED = [False]


def _daily_log_write(line):
    """Best-effort bounded daily rotation; never participates in control."""
    day = datetime.now(NY).date()
    log_dir = os.path.join(_BOT_DIR, "logs")
    if os.path.lexists(log_dir) and (not os.path.isdir(log_dir)
                                       or os.path.islink(log_dir)):
        raise OSError("logs path is not a regular directory")
    os.makedirs(log_dir, exist_ok=True)
    base = os.path.join(log_dir, f"bot_{day.isoformat()}.log")
    encoded = (line + "\n").encode("utf-8", "backslashreplace")
    try:
        size = os.path.getsize(base)
    except OSError:
        size = 0
    if size + len(encoded) > _LOG_MAX_BYTES:
        oldest = f"{base}.{_LOG_MAX_SEGMENTS - 1}"
        if os.path.isfile(oldest) and not os.path.islink(oldest):
            os.remove(oldest)
        for index in range(_LOG_MAX_SEGMENTS - 2, 0, -1):
            source = f"{base}.{index}"
            if os.path.isfile(source) and not os.path.islink(source):
                os.replace(source, f"{base}.{index + 1}")
        if os.path.isfile(base) and not os.path.islink(base):
            os.replace(base, f"{base}.1")
    with open(base, "ab") as stream:
        stream.write(encoded)
    if _LOG_CLEANED_DAY[0] != day.isoformat():
        _LOG_CLEANED_DAY[0] = day.isoformat()
        cutoff = day - timedelta(days=_LOG_KEEP_DAYS)
        for name in os.listdir(log_dir):
            if not name.startswith("bot_") or ".log" not in name:
                continue
            try:
                stamped = date.fromisoformat(name[4:14])
                target = os.path.join(log_dir, name)
                if (stamped < cutoff and os.path.isfile(target)
                        and not os.path.islink(target)):
                    os.remove(target)
            except Exception:
                continue


def log(msg):
    """v3.7.13 (H3): log() NEVER raises — a full disk / dead stdout must not
    kill the poll (the P1 no-new-risk machinery must survive a disk so full
    that even its own logging fails). One stderr fallback attempt, else the
    line is dropped silently — losing a log line is always better than
    losing the rails."""
    try:
        stamp = f"{datetime.now(NY):%Y-%m-%d %H:%M:%S} NY"
    except BaseException:
        # Timestamping is presentation only.  In particular, a broken host
        # wall clock must not turn a safety diagnostic into a control-flow
        # exception that skips this poll's rails or close service.
        stamp = "TIME-UNAVAILABLE NY"
    line = f"{stamp} | {msg}"
    try:
        print(line, flush=True)
    except Exception:
        try:
            sys.stderr.write(line + "\n"); sys.stderr.flush()
        except Exception:
            pass
    try:
        _daily_log_write(line)
        _LOG_WRITE_WARNED[0] = False
    except Exception as exc:
        if not _LOG_WRITE_WARNED[0]:
            _LOG_WRITE_WARNED[0] = True
            warning = (f"{stamp} | [WARN] daily log unavailable "
                       f"({type(exc).__name__}: "
                       f"{exc}); console and trading protections continue")
            try:
                print(warning, flush=True)
            except Exception:
                try: sys.stderr.write(warning + "\n"); sys.stderr.flush()
                except Exception: pass

# ============================================================ STATE (crash-safe)
_STATE_LOAD_STATUS = ["unknown"]  # missing | loaded | custody-only | unreadable
_STATE_IMAGE_SCHEMA = "state_image/1"
_STATE_IMAGE_KEY = "_state_image"
_STATE_GENERATION = [0]
# Complete, parse/digest-valid primary/tmp/backup images observed by the most
# recent load.  File timestamps are intentionally absent: takeover authority
# comes from signed generations, monotonic records and fixed path roles only.
_STATE_RECOVERY_CANDIDATES = [[]]
_STATE_PREDECESSOR_SLOT_BLOCKERS = [[]]
_STATE_PREDECESSOR_TORN_SLOTS = [[]]
_TAKEOVER_JOURNAL_SUFFIX = ".predecessor-takeover"


def _strict_json_pairs(pairs):
    """Reject duplicate object keys instead of silently taking the last one."""
    out = {}
    for key, value in pairs:
        if key in out:
            raise ValueError(f"duplicate JSON object key {key!r}")
        out[key] = value
    return out


def _reject_json_constant(value):
    raise ValueError(f"non-finite JSON constant {value!r}")


def _strict_json_value(value):
    """True only for the finite, string-keyed JSON data model.

    ``json.dump(default=str)`` used to turn an accidental date, exception or
    broker object into authoritative state.  It also emitted NaN/Infinity,
    which Python would read back even though neither value is JSON.  State is
    safety authority, so unsupported values must make the save fail loudly.
    """
    if value is None or isinstance(value, (str, bool)):
        return True
    if isinstance(value, int) and not isinstance(value, bool):
        return True
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, list):
        return all(_strict_json_value(item) for item in value)
    if isinstance(value, dict):
        return all(isinstance(key, str) and _strict_json_value(item)
                   for key, item in value.items())
    return False


def _state_body_digest(body):
    if not isinstance(body, dict) or not _strict_json_value(body):
        return None
    try:
        raw = json.dumps(
            body, sort_keys=True, separators=(",", ":"), ensure_ascii=False,
            allow_nan=False).encode("utf-8")
    except (TypeError, ValueError, OverflowError):
        return None
    return hashlib.sha256(raw).hexdigest()


def _validated_state_image(obj):
    """Return ``(body, generation, signed)`` for one complete image.

    Legacy V384 images have no envelope and enter generation zero.  Once this
    build saves a lifecycle state, every later primary/temp/backup image is
    generation-ordered and digest-bound.  A partial or forged envelope is
    never downgraded to legacy.
    """
    if not isinstance(obj, dict) or not _strict_json_value(obj):
        return None
    if _STATE_IMAGE_KEY not in obj:
        return copy.deepcopy(obj), 0, False
    meta = obj.get(_STATE_IMAGE_KEY)
    if (not isinstance(meta, dict)
            or set(meta) != {"schema", "generation", "sha256"}
            or meta.get("schema") != _STATE_IMAGE_SCHEMA
            or isinstance(meta.get("generation"), bool)
            or not isinstance(meta.get("generation"), int)
            or not 1 <= meta.get("generation", 0) <= 9_007_199_254_740_991
            or not isinstance(meta.get("sha256"), str)
            or len(meta.get("sha256", "")) != 64
            or any(ch not in "0123456789abcdef"
                   for ch in meta.get("sha256", ""))):
        return None
    body = copy.deepcopy(obj)
    body.pop(_STATE_IMAGE_KEY, None)
    digest = _state_body_digest(body)
    if digest is None or digest != meta["sha256"]:
        return None
    return body, int(meta["generation"]), True


def _read_state_image(path):
    if os.path.islink(path) or not os.path.isfile(path):
        return None
    try:
        with open(path, encoding="utf-8") as stream:
            obj = json.load(
                stream, object_pairs_hook=_strict_json_pairs,
                parse_constant=_reject_json_constant)
        checked = _validated_state_image(obj)
        if checked is None:
            raise ValueError("invalid state image digest/JSON model")
        body, generation, signed = checked
        return {"path": path, "body": body, "generation": generation,
                "signed": signed}
    except Exception as exc:
        log(f"!! state {path} unreadable ({exc}) — fallback")
        return None


def _state_terminal_authority(body):
    """Monotonic authorities which may outrank an otherwise newer image."""
    if not isinstance(body, dict):
        return 0
    bound = _supported_state_image_identity_bound(body)
    if bound:
        ranks = []
        takeover = body.get("_predecessor_takeover")
        if _valid_predecessor_takeover_txn(takeover, body):
            # Manual review is a monotonic strengthening of every active
            # pre-commit stage.  It must survive beside a newer-looking active
            # image after a torn two-file rotation, while a genuinely committed
            # receipt remains the strongest takeover authority and must re-prove
            # its recovery pair before it can release new risk.
            if takeover.get("status") == "MANUAL_REVIEW":
                # A review raised while repairing a lone COMMITTED image keeps
                # the already-proved anchor marker and revokes that incomplete
                # commit. It must outrank the stale one-image receipt; ordinary
                # pre-commit review stays below a valid COMMITTED pair.
                ranks.append(292 if takeover.get("anchor_status") == "PROVED"
                             else 288)
            else:
                ranks.append({
                    "QUARANTINED": 280,
                    "INVENTORY_RECONCILED": 282,
                    "ANCHOR_WAIT": 284,
                    "ANCHOR_PROVED": 286,
                    "COMMITTED": 290,
                }.get(takeover.get("stage"), 280))
        if _valid_target_hit(body.get("_target_hit"), body):
            ranks.append(400)
        r4_record = body.get("_r4_migration")
        if _valid_r4_migration(r4_record, body):
            # The committed one-time r4 migration is irreversible: it must
            # outrank every archived takeover stage so recovery selection can
            # never roll a migrated folder back to its pre-migration mate.
            ranks.append(296 if r4_record.get("stage") == "COMMITTED"
                         else 291)
        guard = body.get("_external_cashflow_guard")
        if (isinstance(guard, dict)
                and guard.get("schema") ==
                    _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA
                and _valid_external_cashflow_guard(guard, body)):
            # Guard-4 is an irreversible repair boundary.  It outranks every
            # active takeover stage, but target/export terminal custody stays
            # stronger.  Generation still orders ordinary guard-4 updates.
            ranks.append(295)
        txn = body.get("_continuity_export_txn")
        if _valid_continuity_export_txn(txn, body):
            # Export settlement is a monotonic transaction layered on the
            # immutable hit.  Generation alone must never let a newer stale
            # LEDGERS_SETTLED image roll an already committed producer receipt
            # backward.  The gaps also leave room for future substages without
            # collapsing them onto the bare-target rank.
            ranks.append({
                "PREPARED": 410,
                # STEP_PROVEN returns to PREPARED after both ledgers consume
                # the step.  These two substages therefore share a rank and
                # generation orders their normal forward/backward-looking
                # crash images; ranking STEP_PROVEN higher would revive a
                # partially consumed older backup.
                "STEP_PROVEN": 410,
                "LEDGERS_SETTLED": 430,
                "ARTIFACT_COMMITTED": 440,
            }.get(txn.get("stage"), 300))
        if (_valid_target_watch(body.get("_target_flat_watch"), body)
                or _valid_post_hit_catchup(
                    body.get("_post_hit_catchup"), body)):
            ranks.append(300)
        if ranks:
            return max(ranks)
    recovery = body.get("_safety_recovery_pending")
    if (_supported_state_image_identity_bound(body)
            and _valid_safety_recovery_pending(recovery, body)):
        # A surviving PENDING image means the multi-image clear did not prove
        # completion.  It must beat a COMMITTED peer.  A fully COMMITTED
        # receipt, in turn, is the only ordinary authority allowed to beat
        # the older hard-rail halt it proves was cleared.
        return 260 if recovery.get("status") == "PENDING" else 250
    halt = body.get("_close_only_halt")
    if (_supported_state_image_identity_bound(body)
            and _valid_close_only_halt_record(halt)
            and halt.get("reason") != "keyboard interrupt"):
        return 220
    if (_supported_state_image_identity_bound(body)
            and _valid_ledger_recovery_halt(
                body.get("_ledger_recovery_halt"))):
        return 210
    return 0


def _state_monotonic_presence(body):
    """Rank identity-bound terminal *claims*, even when their bytes are bad.

    A malformed stop cannot be treated as though its key never existed and
    rolled back to an older executable image.  This predicate is deliberately
    presence-sensitive; validity remains the separate terminal-authority
    predicate above.  A strictly stronger valid terminal image may supersede a
    weaker malformed claim (for example, a proved TARGET HIT beats an old torn
    close-only halt), but equality never does.
    """
    if (not isinstance(body, dict)
            or not _state_image_internally_bound(body)):
        return 0
    ranks = []
    if "_target_hit" in body:
        ranks.append(400)
    if "_r4_migration" in body:
        record = body.get("_r4_migration")
        stage = record.get("stage") if isinstance(record, dict) else None
        ranks.append(296 if stage == "COMMITTED" else 291)
    if "_continuity_export_txn" in body:
        txn = body.get("_continuity_export_txn")
        stage = txn.get("stage") if isinstance(txn, dict) else None
        # Presence remains conservative: a torn committed-stage claim cannot
        # be erased by falling back to a weaker executable image merely because
        # the receipt itself needs inspected recovery.
        ranks.append({
            "PREPARED": 410,
            "STEP_PROVEN": 410,
            "LEDGERS_SETTLED": 430,
            "ARTIFACT_COMMITTED": 440,
        }.get(stage, 410))
    if "_predecessor_takeover" in body:
        takeover = body.get("_predecessor_takeover")
        stage = takeover.get("stage") if isinstance(takeover, dict) else None
        status = takeover.get("status") if isinstance(takeover, dict) else None
        if status == "MANUAL_REVIEW":
            # Presence is deliberately conservative even when subordinate
            # bytes are torn: a malformed review claim may never roll back to
            # an executable active stage. A review produced from a partial
            # commit retains PROVED solely to revoke that lone receipt.
            ranks.append(292 if takeover.get("anchor_status") == "PROVED"
                         else 288)
        else:
            ranks.append({
                "QUARANTINED": 280,
                "INVENTORY_RECONCILED": 282,
                "ANCHOR_WAIT": 284,
                "ANCHOR_PROVED": 286,
                "COMMITTED": 290,
            }.get(stage, 280))
    guard = body.get("_external_cashflow_guard")
    qualified_only = {
        "source_guard_sha256", "takeover_inventory_sha256",
        "qualified_broad_start_epoch", "qualified_takeover_started_msc",
        "qualified_prefix_sha256", "qualified_prefix_count",
        "qualified_full_sha256", "qualified_full_count",
        "qualified_receipt_sha256",
    }
    if (isinstance(guard, dict)
            and (guard.get("schema") ==
                 _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA
                 or any(key in guard for key in qualified_only))):
        # Presence is conservative even when one guard-4 field is torn: never
        # roll an attempted one-way repair back into executable guard-3.
        ranks.append(295)
    if any(key in body for key in (
            "_target_flat_watch", "_post_hit_catchup")):
        ranks.append(300)
    if "_safety_recovery_pending" in body:
        recovery = body.get("_safety_recovery_pending")
        ranks.append(250 if (_valid_safety_recovery_pending(recovery, body)
                             and recovery.get("status") == "COMMITTED")
                     else 260)
    if "_close_only_halt" in body:
        halt = body.get("_close_only_halt")
        # A valid operator keyboard stop is explicitly resumable.  A malformed
        # record which merely says "keyboard" is not allowed that privilege.
        if (not _valid_close_only_halt_record(halt)
                or halt.get("reason") != "keyboard interrupt"):
            ranks.append(220)
    if "_ledger_recovery_halt" in body:
        ranks.append(210)
    return max(ranks or [0])


def _promote_recovered_temp(path):
    if path != STATE_FILE + ".tmp":
        return
    if os.path.isfile(STATE_FILE) and not os.path.islink(STATE_FILE):
        # Rotation failure is not a successful recovery.  Let the caller latch
        # persistence NNR instead of logging that the temp was promoted while
        # silently continuing from an in-memory image the disk did not accept.
        os.replace(STATE_FILE, STATE_FILE + ".bak")
    os.replace(path, STATE_FILE)


def _current_state_image_identity_bound(obj):
    """Prove one complete v3 state image belongs to the bound MT5 account."""
    return bool(
        isinstance(obj, dict)
        and _valid_lifecycle_binding(obj.get("_lifecycle_binding"))
        and _supported_state_image_identity_bound(obj))



def _state_image_internally_bound(obj):
    """Prove lifecycle/account/start identity without trusting the live login."""
    if not isinstance(obj, dict):
        return False
    binding = obj.get("_lifecycle_binding")
    identity = obj.get("mt5_identity")
    start = obj.get("start_balance")
    return bool(
        _valid_supported_lifecycle_binding(binding)
        and isinstance(identity, dict)
        and set(identity) == {"login", "server"}
        and isinstance(identity.get("login"), int)
        and not isinstance(identity.get("login"), bool)
        and identity.get("login", 0) > 0
        and isinstance(identity.get("server"), str)
        and bool(identity.get("server"))
        and (identity["login"], identity["server"])
            == (binding["login"], binding["server"])
        and _finite_num(start, positive=True)
        and abs(float(start)
                - binding["observed_start_cents"] / 100.0) <= 1e-9)


def _supported_state_image_identity_bound(obj):
    """Prove current or exact predecessor lifecycle/account/start identity.

    This broader predicate is custody authority only.  It lets monotonic
    target/export presence in a V380/V381 recovery image outrank an older
    active primary, but never makes that predecessor strategy-resumable.
    """
    if not _state_image_internally_bound(obj):
        return False
    binding = obj.get("_lifecycle_binding")
    return bool(
        (_BOOT_IDENT[0] is None
             or _BOOT_IDENT[0] == (binding["login"], binding["server"]))
    )


def _state_recovery_semantically_valid(obj):
    """Validate an ordinary primary/backup candidate before it may win.

    CLI/live-account matching is deliberately deferred to the later boot and
    lifecycle gates so a valid state from another recipe/account is refused,
    never replaced by an older local image.  Internal identity, one-shot
    recipe markers, gate authority, and all safety records must already be
    coherent here; a merely parseable corrupt primary can therefore fall back
    to a valid backup.
    """
    if not _state_image_internally_bound(obj):
        return False
    checked = obj
    binding = obj.get("_lifecycle_binding")
    if not _valid_lifecycle_binding(binding):
        predecessor_terminal = bool(
            _valid_predecessor_terminal_custody_binding(binding)
            and any(key in obj for key in _V382_TERMINAL_MIGRATION_KEYS))
        # Active no-capital predecessors have one deliberately supported
        # migration into V385.  Validate a detached current-schema view during
        # recovery selection so the old wrapper itself cannot force a valid
        # main/backup pair into custody-only before the real atomic migration
        # gets a chance to run. Terminal/hash-chained predecessors still
        # return None; capital-bound predecessors receive only the separate
        # validation-only view below and remain non-migratable.
        checked = (obj if predecessor_terminal else
                   _v382_upgrade_active_binding_candidate(obj))
        if (checked is None
                and _valid_supported_lifecycle_binding(binding)
                and binding.get("declared_capital_cents") is not None):
            # Capital-bound predecessors remain valid recovery images, but
            # their token meant sizing-only.  Build a detached schema-8 view
            # solely for structural validation; startup refuses the untouched
            # predecessor before any broker/state mutation, so this view can
            # never authorize full-virtual trading economics.
            checked = _v382_upgrade_active_binding_candidate(
                obj, validation_only=True)
        if checked is None:
            return False
        binding = checked.get("_lifecycle_binding")
    if (binding.get("recipe") in {
            "p2-fresh", "p2-adopt", "p2-standalone-immediate"}
            and checked.get("rearm_done") is not True):
        return False
    if not _state_economic_fields_valid(checked):
        return False
    watch = checked.get("_target_flat_watch")
    if (isinstance(watch, dict)
            and watch.get("schema") == _LEGACY_TARGET_WATCH_SCHEMA
            and _valid_legacy_target_watch_impl(watch, None)):
        upgraded_watch = _legacy_target_watch_upgrade_record(obj, watch)
        if upgraded_watch is not None:
            checked = dict(obj)
            checked["_target_flat_watch"] = upgraded_watch
            watch = upgraded_watch
    hit = checked.get("_target_hit")
    post = checked.get("_post_hit_catchup")
    # Target-only custody intentionally preserves an exact raw ledger preimage
    # for later audit.  Give recovery selection the same narrow waiver as the
    # terminal service: an exact current watch, or a valid HIT paired with its
    # hash-bound AUDIT_REQUIRED record.  No ordinary active image receives it.
    terminal_ledger_quarantine = bool(
        _valid_current_target_watch_impl(watch, checked)
        or (_valid_target_hit(hit, checked)
            and isinstance(post, dict)
            and post.get("stage") == "AUDIT_REQUIRED"
            and _valid_post_hit_catchup(post, checked)))
    target_missing_handoff = bool(
        _valid_target_hit(hit, checked)
        and "_post_hit_catchup" not in checked
        and "_continuity_export_txn" not in checked)
    return bool(
        _validate_safety_records(
            checked, log_bad=False,
            allow_target_ledger_quarantine=terminal_ledger_quarantine,
            allow_target_missing_handoff=target_missing_handoff)
        and _validate_gate_start_authority(checked, log_bad=False)
    )


def _state_economic_fields_valid(obj):
    """Read-only total validator for optional persisted controller fields."""
    if not isinstance(obj, dict):
        return False
    book = obj.get("book_returns")
    if ("book_returns" in obj
            and (not isinstance(book, list)
                 or any(not _finite_num(value)
                        or not -1.0 <= float(value) <= 10.0
                        for value in book))):
        return False
    dips = obj.get("dip_hist")
    if ("dip_hist" in obj
            and (not isinstance(dips, list)
                 or any(not _finite_num(value)
                        or not 0.0 <= float(value) <= 1.0
                        for value in dips))):
        return False
    max_dip = obj.get("max_dip20")
    if "max_dip20" in obj:
        if (not _finite_num(max_dip)
                or not 0.004 <= float(max_dip) <= 1.0):
            return False
        if (isinstance(dips, list) and dips
                and not math.isclose(
                    float(max_dip),
                    max(max(float(value) for value in dips), 0.004),
                    rel_tol=0.0, abs_tol=1e-12)):
            return False
    for key, low, high in (
            ("_last_L", 0.0, MAX_LEVERAGE),
            ("_sess_dip", -1.0, 0.0),
            ("_last_book_ret", -1.0, 1.0)):
        if (key in obj and (not _finite_num(obj.get(key))
                            or not low <= float(obj[key]) <= high)):
            return False
    for key, upper in (("trading_days", 200_000),
                       ("dip_live_n", 1_000_000)):
        value = obj.get(key)
        if (key in obj and (isinstance(value, bool)
                            or not isinstance(value, int)
                            or not 0 <= value <= upper)):
            return False
    sd_session = obj.get("_sd_sess")
    if ("_sd_sess" in obj and sd_session is not None
            and not _canonical_iso_date(sd_session)):
        return False
    dc = obj.get("_daycount")
    if dc is not None:
        if (not isinstance(dc, dict)
                or _continuity_session(dc.get("session")) is None
                or not _finite_num(dc.get("last_eq"), positive=True)):
            return False
    return True


def _state_tmp_recoverable(obj):
    """Accept only a complete, identity/recipe-bound crash-left state image."""
    if not isinstance(obj, dict):
        return False
    binding = obj.get("_lifecycle_binding")
    identity = obj.get("mt5_identity")
    start = obj.get("start_balance")
    if (not _valid_supported_lifecycle_binding(binding)
            or not isinstance(identity, dict)
            or set(identity) != {"login", "server"}
            or not isinstance(identity.get("login"), int)
            or isinstance(identity.get("login"), bool)
            or identity.get("login", 0) <= 0
            or not isinstance(identity.get("server"), str)
            or not bool(identity.get("server"))
            or (identity.get("login"), identity.get("server"))
                != (binding.get("login"), binding.get("server"))
            or (_BOOT_IDENT[0] is not None
                and _BOOT_IDENT[0] != (binding["login"], binding["server"]))
            or not _finite_num(start, positive=True)
            or abs(float(start)
                   - binding["observed_start_cents"] / 100.0) > 1e-9):
        return False
    if not _typed_profile_matches_binding(binding):
        return False
    if (binding["recipe"] in {
            "p2-fresh", "p2-adopt", "p2-standalone-immediate"}
            and obj.get("rearm_done") is not True):
        return False
    checked = _v382_upgrade_active_binding_candidate(obj)
    if checked is None:
        # Current terminal images validate without an active-state migration;
        # predecessor terminal hash chains remain permanent NNR and are not
        # selected as a strategy-resumable crash temp.
        checked = (obj if (_valid_lifecycle_binding(binding)
                           or (_valid_predecessor_terminal_custody_binding(
                                   binding)
                               and any(key in obj for key in
                                       _V382_TERMINAL_MIGRATION_KEYS)))
                   else None)
    if checked is None:
        return False
    current_watch = checked.get("_target_flat_watch")
    if (isinstance(current_watch, dict)
            and current_watch.get("schema") == _LEGACY_TARGET_WATCH_SCHEMA
            and _valid_legacy_target_watch_impl(current_watch, None)):
        # A crash-left V380 image can contain the sole durable target watch
        # beside raw ledger preimages that V381 intentionally quarantines.
        # Convert only this detached validation image so that the newer temp
        # can win recovery; normal lifecycle startup performs the durable
        # conversion after load.  Never rewrite the candidate while deciding.
        upgraded_watch = _legacy_target_watch_upgrade_record(
            checked, current_watch)
        if upgraded_watch is not None:
            if checked is obj:
                checked = dict(checked)
            checked["_target_flat_watch"] = upgraded_watch
            current_watch = upgraded_watch
    terminal_watch = bool(
        _valid_terminal_custody_lifecycle_binding(
            checked.get("_lifecycle_binding"))
        and isinstance(current_watch, dict)
        and current_watch.get("schema") == _TARGET_WATCH_SCHEMA
        and _valid_current_target_watch_impl(current_watch, checked))
    current_hit = checked.get("_target_hit")
    target_missing_handoff = bool(
        _valid_target_hit(current_hit, checked)
        and "_post_hit_catchup" not in checked
        and "_continuity_export_txn" not in checked)
    return _validate_safety_records(
        checked, log_bad=False,
        allow_target_ledger_quarantine=terminal_watch,
        allow_target_missing_handoff=target_missing_handoff)


def load_state():
    """Load one validated, generation-ordered crash image.

    File mtimes are presentation metadata and can move backwards/forwards on a
    restore, copy or clock correction.  They are never state authority.  A
    crash temp may win only with a valid digest and a strictly newer generation
    than both settled images (or through a stronger monotonic target/recovery
    authority).  Thus an old temp can never resurrect merely because its mtime
    was touched.
    """
    tmp = STATE_FILE + ".tmp"
    normal_paths = (STATE_FILE, tmp, STATE_FILE + ".bak")
    journal = STATE_FILE + _TAKEOVER_JOURNAL_SUFFIX
    paths = normal_paths + (journal,)
    _STATE_RECOVERY_CANDIDATES[0] = []
    _STATE_PREDECESSOR_SLOT_BLOCKERS[0] = []
    _STATE_PREDECESSOR_TORN_SLOTS[0] = []
    # A prior process' in-memory proof never survives a restart. COMMITTED is
    # strategy authority only after this process re-reads both recovery files.
    if "_TAKEOVER_PAIR_PROVED" in globals():
        _TAKEOVER_PAIR_PROVED[0] = False
    if "_TAKEOVER_SCALE_PAIR_PROVED" in globals():
        _TAKEOVER_SCALE_PAIR_PROVED[0] = False
    if "_TAKEOVER_MANUAL_PAIR_SHA" in globals():
        _TAKEOVER_MANUAL_PAIR_SHA[0] = None
    if "_TAKEOVER_QUIET_WITNESS" in globals():
        _TAKEOVER_QUIET_WITNESS[0] = None
    if "_QUALIFIED_CASHFLOW_REPAIR_WITNESS" in globals():
        _QUALIFIED_CASHFLOW_REPAIR_WITNESS[0] = None
    if "_QUALIFIED_CASHFLOW_PAIR_PROVED" in globals():
        _QUALIFIED_CASHFLOW_PAIR_PROVED[0] = False
    if "_QUALIFIED_CASHFLOW_NEEDS_REPROOF" in globals():
        _QUALIFIED_CASHFLOW_NEEDS_REPROOF[0] = False
    if "_QUALIFIED_CASHFLOW_STATUS_SIGNATURE" in globals():
        _QUALIFIED_CASHFLOW_STATUS_SIGNATURE[0] = None
    if "_QUALIFIED_CASHFLOW_PROPOSAL_INVENTORY" in globals():
        _QUALIFIED_CASHFLOW_PROPOSAL_INVENTORY[0] = None
    if "_QUALIFIED_CASHFLOW_PROPOSAL_DISK" in globals():
        _QUALIFIED_CASHFLOW_PROPOSAL_DISK[0] = None
    saw_state_file = any(os.path.lexists(path) for path in paths)
    candidates = []
    for path in paths:
        if not os.path.lexists(path):
            continue
        item = _read_state_image(path)
        if item is None:
            if path == journal:
                # A torn journal may contain the only copy of the three-slot
                # predecessor manifest. Never fall back through it.
                _STATE_LOAD_STATUS[0] = "unreadable"
                _STATE_PREDECESSOR_SLOT_BLOCKERS[0] = [path]
                log("[WARN] predecessor takeover journal is unreadable — "
                    "absolute no-write/no-broker refusal")
                return {}
            _STATE_PREDECESSOR_SLOT_BLOCKERS[0].append(path)
            continue
        candidates.append(item)
    if "_QUALIFIED_CASHFLOW_NEEDS_REPROOF" in globals():
        normal_guard4 = []
        for expected_path in (STATE_FILE, STATE_FILE + ".bak"):
            matches = [item for item in candidates
                       if item["path"] == expected_path]
            if len(matches) != 1:
                normal_guard4 = []
                break
            body = matches[0]["body"]
            guard = (body.get("_external_cashflow_guard")
                     if isinstance(body, dict) else None)
            if (not isinstance(guard, dict)
                    or guard.get("schema") !=
                        _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA
                    or not _valid_external_cashflow_guard(guard, body)):
                normal_guard4 = []
                break
            # A normal save intentionally rotates two successive mutable
            # state generations through primary/backup.  Guard-4 publication
            # authority is the immutable, self-digesting receipt, not an
            # equality claim over those complete runtime bodies.
            normal_guard4.append(copy.deepcopy(guard))
        qualified_only = {
            "source_guard_sha256", "takeover_inventory_sha256",
            "qualified_broad_start_epoch",
            "qualified_takeover_started_msc",
            "qualified_prefix_sha256", "qualified_prefix_count",
            "qualified_full_sha256", "qualified_full_count",
            "qualified_receipt_sha256",
        }
        any_guard4 = any(
            isinstance(item.get("body"), dict)
            and isinstance(item["body"].get("_external_cashflow_guard"), dict)
            and (item["body"]["_external_cashflow_guard"].get("schema") ==
                 _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA
                 or any(key in item["body"]["_external_cashflow_guard"]
                        for key in qualified_only))
            for item in candidates)
        _QUALIFIED_CASHFLOW_NEEDS_REPROOF[0] = bool(
            any_guard4 and not (
                len(normal_guard4) == 2
                and normal_guard4[0] == normal_guard4[1]))
    # Preserve complete validated images for the later predecessor planner.
    # The planner independently checks lifecycle/account semantics before use;
    # this snapshot merely prevents load selection from erasing a valid
    # monotonic intent that survived only in backup or a crash temp.
    _STATE_RECOVERY_CANDIDATES[0] = copy.deepcopy([
        item for item in candidates if item["path"] in normal_paths])
    if not candidates:
        _STATE_LOAD_STATUS[0] = "unreadable" if saw_state_file else "missing"
        return {}

    _STATE_GENERATION[0] = max(
        [_STATE_GENERATION[0]] + [item["generation"] for item in candidates])
    path_priority = {
        STATE_FILE + ".bak": 0,
        tmp: 1,
        STATE_FILE: 2,
        journal: 3,
    }
    for item in candidates:
        item["authority"] = _state_terminal_authority(item["body"])
        item["presence_authority"] = _state_monotonic_presence(item["body"])
        item["priority"] = path_priority.get(item["path"], -1)
        item["semantic_valid"] = _state_recovery_semantically_valid(
            item["body"])
        item["tmp_recoverable"] = bool(
            item["path"] != tmp or _state_tmp_recoverable(item["body"]))
        if (item["path"] in normal_paths
                and not item["semantic_valid"]):
            _STATE_PREDECESSOR_TORN_SLOTS[0].append(item["path"])

    newest_generation = max(item["generation"] for item in candidates)
    malformed_newest = [
        item for item in candidates
        if item["generation"] == newest_generation
        and not item["semantic_valid"]
        and _state_image_internally_bound(item["body"])]
    strongest_valid_authority = max(
        [item["authority"] for item in candidates
         if item["semantic_valid"]] or [0])
    malformed_newest_authority = max(
        [max(item["authority"], item["presence_authority"])
         for item in malformed_newest] or [0])
    if (malformed_newest
            and strongest_valid_authority <= malformed_newest_authority):
        # An older clean backup may predate a stop, ambiguous broker intent,
        # day/finality transaction, or other safety mutation present in the
        # newest digest-valid image.  Semantic corruption cannot prove that
        # those newer bytes never became authoritative, so never roll them
        # back into executable strategy state.  Keep the newest raw body only
        # for bound-account custody/flatten service.
        chosen = max(
            malformed_newest,
            key=lambda item: (max(item["authority"],
                                  item["presence_authority"]),
                              item["priority"]))
        _STATE_LOAD_STATUS[0] = "custody-only"
        log("[WARN] newest generation is internally bound but semantically "
            "malformed — older strategy fallback forbidden; loaded only for "
            "identity-bound account custody")
        return chosen["body"]

    malformed_monotonic = [
        item for item in candidates
        if item["presence_authority"] > 0
        and not item["semantic_valid"]
        and _state_image_internally_bound(item["body"])]
    unsuperseded_malformed = [
        item for item in malformed_monotonic
        if item["presence_authority"] >= strongest_valid_authority]
    if unsuperseded_malformed:
        # Never roll a malformed monotonic target/recovery claim back to an
        # older active image.  Preserve the strongest internally identity-
        # bound raw image as custody-only authority so boot can still cancel/
        # flatten late exposure on the correct account.  A strictly stronger
        # semantically valid terminal image is the only permitted supersession.
        # It is never strategy-resumable and is never rewritten by the loader.
        chosen = max(
            unsuperseded_malformed,
            key=lambda item: (item["presence_authority"],
                              item["generation"], item["priority"]))
        _STATE_LOAD_STATUS[0] = "custody-only"
        log("[WARN] malformed monotonic state authority present — loaded "
            "only for identity-bound account custody; strategy fallback and "
            "state rewrite are forbidden")
        return chosen["body"]

    strongest = strongest_valid_authority
    pool = ([item for item in candidates
             if item["authority"] == strongest and item["semantic_valid"]]
            if strongest else
            [item for item in candidates if item["semantic_valid"]])
    settled = [item for item in candidates
               if item["path"] != tmp and item["semantic_valid"]]
    settled_generation = max(
        [item["generation"] for item in settled] or [-1])
    if strongest == 0:
        # A legacy generation-zero temp has no freshness proof.  A signed temp
        # must be strictly newer than both primary and backup; equality selects
        # the settled primary and cannot roll it back.
        pool = [item for item in pool
                if item["path"] != tmp
                or (item["tmp_recoverable"] and item["signed"]
                    and item["generation"] > settled_generation)
                or (item["tmp_recoverable"] and not settled)]
    else:
        # A monotonic marker may outrank generation, but a crash temp still
        # has to be a complete identity/recipe/safety image.  Marker presence
        # inside an otherwise malformed temp is not recovery authority.
        pool = [item for item in pool if item["tmp_recoverable"]]
    if not pool:
        pool = settled
    if not pool:
        _STATE_LOAD_STATUS[0] = "unreadable"
        log("[WARN] crash temp is digest-readable but not a complete "
            "identity/recipe/safety authority — refusing recovery")
        return {}
    chosen = max(
        pool, key=lambda item: (item["generation"], item["priority"]))

    chosen_binding = (chosen["body"].get("_lifecycle_binding")
                      if isinstance(chosen.get("body"), dict) else None)
    defer_predecessor_temp = bool(
        chosen["path"] == tmp
        and (_valid_v383_lifecycle_binding(chosen_binding)
             or _valid_v384_lifecycle_binding(chosen_binding)
             or _valid_v385_lifecycle_binding(chosen_binding)))
    if chosen["path"] == tmp and defer_predecessor_temp:
        # The crash temp is itself predecessor evidence. Its physical rename
        # would overwrite the old backup before schema-9 has embedded all
        # three slots. Selection is read-only until the dedicated journal is
        # flushed and verified by the predecessor takeover writer (removed
        # with the generic takeover; the ranking semantics remain).
        log("[RESUME] predecessor crash temp selected in memory; physical "
            "promotion deferred until its three-slot takeover journal is "
            "durable")
    elif chosen["path"] == tmp:
        try:
            _promote_recovered_temp(tmp)
        except OSError as exc:
            log(f"[WARN] validated state temp could not be promoted ({exc}); "
                "using it in memory with persistence NNR latched")
            _SAVE_FAILED[0] = True
        else:
            log("[RESUME] recovered digest-valid crash temp with newer "
                "generation/monotonic authority")
    elif chosen["path"] != STATE_FILE:
        kind = ("monotonic safety authority" if strongest else
                "newest validated generation")
        log(f"[RESUME] {kind} recovered from "
            f"{os.path.basename(chosen['path'])}")
    elif os.path.lexists(tmp):
        log("[WARN] stale/equal-generation state temp ignored; settled "
            "authority retained")
    _STATE_LOAD_STATUS[0] = "loaded"
    return chosen["body"]

_LOG_THROTTLE = {}
def _log_throttled(msg, window=600, key=None):
    """v3.7.12 (P3): once per `window` seconds per DISTINCT message — for
    per-poll diagnostics that can repeat with identical content every poll
    (round-31 measured the sleeve-cap line at 408/410 polls: a self-disk-
    filler). The NO-NEW-RISK latch line is deliberately NOT routed through
    this (it must stay per-poll). v3.7.13 (H4): `key` decouples the throttle
    identity from the printed text — a diagnostic embedding a drifting
    number passes a STATIC key so value drift cannot bypass the window; the
    table is bounded (oldest entry evicted past 256 keys)."""
    k = key if key is not None else msg
    try:
        now = float(time.time())
        if not math.isfinite(now):
            raise ValueError("non-finite wall clock")
    except BaseException:
        # Throttling is optional presentation state.  Emit best-effort and
        # return without ever interrupting the caller's protection path.
        log(msg)
        return
    last = _LOG_THROTTLE.get(k)
    if last is not None and now - last < window:
        return
    if k not in _LOG_THROTTLE and len(_LOG_THROTTLE) >= 256:
        _LOG_THROTTLE.pop(min(_LOG_THROTTLE, key=_LOG_THROTTLE.get), None)
    _LOG_THROTTLE[k] = now
    log(msg)

