def _console_note_wait(reason, session=None):
    """Remember one truthful no-entry reason for the current session.

    This is presentation-only, process-local metadata.  It cannot authorize
    an order or alter an economic ledger, and a restart merely falls back to
    the durable gate/latch state when the day summary is rendered.
    """
    try:
        key = session or ny_session_key()
        _CONSOLE_WAIT_REASONS[str(key)] = str(reason)
        while len(_CONSOLE_WAIT_REASONS) > 16:
            _CONSOLE_WAIT_REASONS.pop(next(iter(_CONSOLE_WAIT_REASONS)))
    except Exception:
        pass


def _finite_num(value, *, positive=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    try:
        value = float(value)
    except Exception:
        return False
    return math.isfinite(value) and (value > 0 if positive else True)


def _canonical_iso_date(value):
    if not isinstance(value, str):
        return False
    try:
        return date.fromisoformat(value).isoformat() == value
    except (TypeError, ValueError):
        return False


def _valid_close_only_halt_record(value):
    """Total shape check for the persisted close-only authority."""
    if not isinstance(value, dict):
        return False
    allowed = {"schema", "reason", "since", "last_flat", "checked_at"}
    if (set(value) - allowed
            or value.get("schema") != "close_only_halt/1"
            or not isinstance(value.get("reason"), str)
            or not value.get("reason")
            or not _finite_num(value.get("since"), positive=True)):
        return False
    if ("last_flat" in value
            and not isinstance(value.get("last_flat"), bool)):
        return False
    if ("checked_at" in value
            and not _finite_num(value.get("checked_at"), positive=True)):
        return False
    return True


def _halt_reason_severity(reason):
    """Conservative total order for competing close-only authorities.

    A weak resumable operator stop must never mask a later permanent rail or
    ambiguous-broker-outcome halt.  Unknown future permanent reasons sit above
    operational/transient reasons and below the hard account floor.
    """
    if not isinstance(reason, str) or not reason:
        return -1
    normalized = reason.lower()
    if normalized == "max-loss floor":
        return 100
    if normalized.startswith("invalid pre-health time authority:"):
        return 95
    if normalized.startswith("ambiguous close "):
        return 90
    if normalized == "external cashflow":
        return 85
    if normalized.startswith("orphan exposure recovery"):
        return 80
    if normalized.startswith("hard-rail service error:"):
        return 70
    if normalized == "keyboard interrupt":
        return 10
    return 60


def _valid_recoverable_hard_rail_reason(reason):
    """Recognize only the exact exception latch emitted by hard rails."""
    prefix = "hard-rail service error: "
    if not isinstance(reason, str) or not reason.startswith(prefix):
        return False
    exception_name = reason[len(prefix):]
    return bool(
        exception_name and len(exception_name) <= 128
        and exception_name.replace("_", "a").isalnum())


def _valid_safety_recovery_pending(value, st=None):
    """Validate the monotonic receipt spanning a multi-image halt clear.

    Presence is blocking.  The embedded original halt lets a later exact
    recovery invocation restore the conservative state after a crash at any
    save boundary; ordinary strategy startup can never interpret the receipt
    as a completed clear.
    """
    keys = {
        "schema", "status", "original_halt", "reason", "login", "server",
        "lifecycle_sha256", "created_at",
    }
    if (not isinstance(value, dict) or set(value) != keys
            or value.get("schema") != _SAFETY_RECOVERY_PENDING_SCHEMA
            or value.get("status") not in {"PENDING", "COMMITTED"}
            or not _valid_close_only_halt_record(
                value.get("original_halt"))
            or value.get("reason") !=
                value.get("original_halt", {}).get("reason")
            or not _valid_recoverable_hard_rail_reason(value.get("reason"))
            or not isinstance(value.get("login"), int)
            or isinstance(value.get("login"), bool)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or not _finite_num(value.get("created_at"), positive=True)):
        return False
    if st is None:
        return True
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    identity = st.get("mt5_identity")
    current_halt = st.get("_close_only_halt")
    return bool(
        _valid_full_virtual_lifecycle_binding(binding)
        and _supported_lifecycle_binding_sha256(binding) ==
            value["lifecycle_sha256"]
        and isinstance(identity, dict)
        and identity.get("login") == value["login"]
        and identity.get("server") == value["server"]
        and (value["status"] == "COMMITTED"
             or current_halt is None
             or current_halt == value["original_halt"]))


def _valid_ledger_recovery_halt(value):
    keys = {"schema", "reason", "since", "daycount_session",
            "shadow_session", "current_session"}
    return bool(
        isinstance(value, dict) and set(value) == keys
        and value.get("schema") == _LEDGER_RECOVERY_HALT_SCHEMA
        and isinstance(value.get("reason"), str) and value["reason"]
        and _finite_num(value.get("since"), positive=True)
        and all(_continuity_session(value.get(key)) is not None
                for key in ("daycount_session", "shadow_session",
                            "current_session")))


def _v389_takeover_ledger_bridge_receipt_sha256(value):
    if not isinstance(value, dict):
        return None
    image = copy.deepcopy(value)
    image.pop("receipt_sha256", None)
    return _state_body_digest(image)


def _valid_v389_takeover_ledger_bridge(value, st=None):
    """Validate the one allowed omission of an unobservable account mark.

    The receipt does not claim a zero return.  It proves that the independent
    strategy/shadow ledger was replayed from terminal D1/M5 evidence while the
    account controller history was preserved byte-for-byte and its next
    measurable interval began at a fresh, identity-bound equity observation.
    """
    keys = {
        "schema", "status", "login", "server", "lifecycle_sha256",
        "takeover_sha256", "cashflow_guard_sha256", "halt_sha256",
        "reason", "source_session", "current_session",
        "source_daycount_sha256", "source_shadow_sha256",
        "replayed_shadow_sha256", "replayed_s8v_sha256",
        "controller_preimage_sha256", "controller_postimage_sha256",
        "baseline_balance_cents", "baseline_credit_cents",
        "baseline_equity", "omitted_account_returns",
        "replayed_shadow_sessions", "created_at", "receipt_sha256",
    }
    if (not isinstance(value, dict) or set(value) != keys
            or value.get("schema") !=
                _V389_TAKEOVER_LEDGER_BRIDGE_SCHEMA
            or value.get("status") != "COMMITTED"
            or not isinstance(value.get("login"), int)
            or isinstance(value.get("login"), bool)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or value.get("reason") != _V389_TAKEOVER_LEDGER_GAP_REASON
            or value.get("omitted_account_returns") != 1
            or isinstance(value.get("omitted_account_returns"), bool)
            or value.get("replayed_shadow_sessions") != 1
            or isinstance(value.get("replayed_shadow_sessions"), bool)
            or not _finite_num(value.get("baseline_equity"), positive=True)
            or not _finite_num(value.get("created_at"), positive=True)):
        return False
    for key in ("baseline_balance_cents", "baseline_credit_cents"):
        raw = value.get(key)
        if (isinstance(raw, bool) or not isinstance(raw, int)
                or (key == "baseline_balance_cents" and raw <= 0)
                or (key == "baseline_credit_cents" and raw != 0)):
            return False
    for key in (
            "lifecycle_sha256", "takeover_sha256",
            "cashflow_guard_sha256", "halt_sha256",
            "source_daycount_sha256", "source_shadow_sha256",
            "replayed_shadow_sha256", "replayed_s8v_sha256",
            "controller_preimage_sha256", "controller_postimage_sha256",
            "receipt_sha256"):
        if not _lower_hex64(value.get(key)):
            return False
    source = _continuity_session(value.get("source_session"))
    current = _continuity_session(value.get("current_session"))
    try:
        adjacent = (source is not None and current is not None
                    and _next_strategy_session_key(source) == current)
    except Exception:
        adjacent = False
    if (not adjacent
            or value["controller_preimage_sha256"] !=
                value["controller_postimage_sha256"]
            or _v389_takeover_ledger_bridge_receipt_sha256(value) !=
                value["receipt_sha256"]):
        return False
    if st is None:
        return True
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    takeover = st.get("_predecessor_takeover")
    guard = st.get("_external_cashflow_guard")
    identity = st.get("mt5_identity")
    dc = st.get("_daycount")
    shadow = st.get("shadow")
    if (not _valid_lifecycle_binding(binding)
            or not _valid_predecessor_takeover_txn(takeover, st)
            or takeover.get("stage") != "COMMITTED"
            or takeover.get("status") != "COMMITTED"
            or takeover.get("anchor_status") != "PROVED"
            or not isinstance(identity, dict)
            or (identity.get("login"), identity.get("server")) !=
                (value["login"], value["server"])
            or (binding.get("login"), binding.get("server")) !=
                (value["login"], value["server"])
            or _lifecycle_binding_sha256(binding) !=
                value["lifecycle_sha256"]
            or _takeover_record_sha256(takeover) !=
                value["takeover_sha256"]
            or _state_body_digest(guard) !=
                value["cashflow_guard_sha256"]
            or not isinstance(dc, dict) or not isinstance(shadow, dict)):
        return False
    dc_session = _continuity_session(dc.get("session"))
    sh_session = _continuity_session(shadow.get("session"))
    if (dc_session is None or sh_session is None
            or dc_session < current or sh_session < current):
        return False
    if (dc_session == current
            and (not _finite_num(dc.get("last_eq"), positive=True)
                 or not math.isclose(
                     float(dc["last_eq"]), float(value["baseline_equity"]),
                     rel_tol=0.0, abs_tol=1e-9))):
        return False
    return True


def _valid_fresh_history_baseline(value):
    keys = {
        "schema", "deals_sha256", "orders_sha256",
        "deal_count", "order_count",
    }
    return bool(
        isinstance(value, dict) and set(value) == keys
        and value.get("schema") == _FRESH_HISTORY_BASELINE_SCHEMA
        and _lower_hex64(value.get("deals_sha256"))
        and _lower_hex64(value.get("orders_sha256"))
        and isinstance(value.get("deal_count"), int)
        and not isinstance(value.get("deal_count"), bool)
        and value.get("deal_count", -1) >= 0
        and isinstance(value.get("order_count"), int)
        and not isinstance(value.get("order_count"), bool)
        and value.get("order_count", -1) >= 0)


def _qualified_takeover_inventory_sha256(value):
    """Bind guard-4 to the immutable predecessor custody manifest.

    Current ``positions/deals/orders`` are intentionally excluded: reductions
    and exits can update them after repair.  They are proved separately while
    the three-poll repair witness is running.  Everything inherited from the
    predecessor remains immutable and is therefore included here.
    """
    if not isinstance(value, dict):
        return None
    return _state_body_digest({
        "schema": "qualified_cashflow_takeover_inventory/1",
        "login": value.get("login"), "server": value.get("server"),
        "source_schema": value.get("source_schema"),
        "recipe": value.get("recipe"),
        "entry_policy": value.get("entry_policy"),
        "observed_start_cents": value.get("observed_start_cents"),
        "declared_capital_cents": value.get("declared_capital_cents"),
        "source_lifecycle_sha256": value.get("source_lifecycle_sha256"),
        "target_lifecycle_sha256": value.get("target_lifecycle_sha256"),
        "candidate_images": value.get("candidate_images"),
        "order_intents": value.get("order_intents"),
        "close_intents": value.get("close_intents"),
        "started_at": value.get("started_at"),
        "source_balance_cents": value.get("source_balance_cents"),
        "source_positions": value.get("source_positions"),
        "source_deals": value.get("source_deals"),
        "source_orders": value.get("source_orders"),
    })


def _qualified_takeover_current_inventory_sha256(value):
    """Bind a Prague-anchor proof to the reconciled takeover inventory.

    Unlike the immutable guard-4 source hash, this receipt deliberately binds
    the exact current positions/deals/orders observed at the proof edge.  The
    takeover commit freezes those fields before normal strategy authority can
    open; later ordinary strategy activity does not rewrite the receipt.
    """
    if not isinstance(value, dict):
        return None
    return _state_body_digest({
        "schema": "qualified_takeover_current_anchor_inventory/1",
        "positions": value.get("positions"),
        "deals": value.get("deals"),
        "orders": value.get("orders"),
    })


def _external_cashflow_guard_base_keys():
    return {
        "schema", "login", "server", "lifecycle_sha256",
        "history_start_epoch", "policy_sha256", "external_sha256",
        "external_count", "unauthorized_trade_sha256",
        "unauthorized_trade_count", "baseline_balance_cents",
        "baseline_credit_cents", "baseline_history_cash_cents",
    }


def _qualified_cashflow_receipt_sha256(value):
    """Domain-separate every guard-4 field except the receipt itself."""
    if not isinstance(value, dict):
        return None
    payload = {key: copy.deepcopy(item) for key, item in value.items()
               if key != "qualified_receipt_sha256"}
    return _state_body_digest({
        "schema": "qualified_external_cashflow_guard_receipt/1",
        "guard": payload,
    })


def _valid_external_cashflow_guard(value, st=None):
    """Validate guard-3 or V387's one-way broker-qualified guard-4."""
    base_keys = _external_cashflow_guard_base_keys()
    qualified_keys = {
        "source_guard_sha256", "takeover_inventory_sha256",
        "qualified_broad_start_epoch", "qualified_takeover_started_msc",
        "qualified_prefix_sha256", "qualified_prefix_count",
        "qualified_full_sha256", "qualified_full_count",
        "qualified_receipt_sha256",
    }
    schema = value.get("schema") if isinstance(value, dict) else None
    expected_keys = (base_keys | qualified_keys
                     if schema == _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA
                     else base_keys)
    if (not isinstance(value, dict) or set(value) != expected_keys
            or schema not in {
                _EXTERNAL_CASHFLOW_GUARD_SCHEMA,
                _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA}
            or isinstance(value.get("login"), bool)
            or not isinstance(value.get("login"), int)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or isinstance(value.get("history_start_epoch"), bool)
            or not isinstance(value.get("history_start_epoch"), int)
            or not 946_684_800 <= value.get("history_start_epoch", 0)
                <= 4_102_444_800
            or not _lower_hex64(value.get("policy_sha256"))
            or not _lower_hex64(value.get("external_sha256"))
            or isinstance(value.get("external_count"), bool)
            or not isinstance(value.get("external_count"), int)
            or not 0 <= value.get("external_count", -1) <= 10_000_000
            or not _lower_hex64(value.get("unauthorized_trade_sha256"))
            or isinstance(value.get("unauthorized_trade_count"), bool)
            or not isinstance(value.get("unauthorized_trade_count"), int)
            or not 0 <= value.get("unauthorized_trade_count", -1)
                <= 10_000_000
            or isinstance(value.get("baseline_balance_cents"), bool)
            or not isinstance(value.get("baseline_balance_cents"), int)
            or value.get("baseline_balance_cents", 0) <= 0
            or isinstance(value.get("baseline_credit_cents"), bool)
            or not isinstance(value.get("baseline_credit_cents"), int)
            or value.get("baseline_credit_cents") != 0
            or isinstance(value.get("baseline_history_cash_cents"), bool)
            or not isinstance(value.get("baseline_history_cash_cents"), int)
            or abs(value.get("baseline_history_cash_cents", 0))
                > 100_000_000_000_000):
        return False
    if schema == _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA:
        if (value.get("qualified_broad_start_epoch") !=
                _QUALIFIED_CASHFLOW_BROAD_START_EPOCH
                or isinstance(value.get("qualified_takeover_started_msc"),
                              bool)
                or not isinstance(value.get("qualified_takeover_started_msc"),
                                  int)
                or value.get("qualified_takeover_started_msc", 0)
                    <= value.get("history_start_epoch", 0) * 1000
                or not _lower_hex64(value.get("source_guard_sha256"))
                or not _lower_hex64(value.get(
                    "takeover_inventory_sha256"))
                or not _lower_hex64(value.get("qualified_prefix_sha256"))
                or not _lower_hex64(value.get("qualified_full_sha256"))
                or not _lower_hex64(value.get("qualified_receipt_sha256"))
                or value.get("qualified_receipt_sha256") !=
                    _qualified_cashflow_receipt_sha256(value)
                or any(isinstance(value.get(key), bool)
                       or not isinstance(value.get(key), int)
                       or not 0 <= value.get(key, -1) <= 10_000_000
                       for key in ("qualified_prefix_count",
                                   "qualified_full_count"))):
            return False
        # The repair recognizes exactly the empty/unqualified guard-3 defect;
        # retain its digest so guard-4 can never be minted as a generic rebase.
        source_guard = {
            key: copy.deepcopy(value[key]) for key in base_keys}
        source_guard["schema"] = _EXTERNAL_CASHFLOW_GUARD_SCHEMA
        source_guard["baseline_history_cash_cents"] = 0
        if (isinstance(st, dict)
                and _valid_lifecycle_binding(
                    st.get("_lifecycle_binding"))
                and isinstance(st.get("_v389_capital_transition"), dict)):
            # Preserve the exact old guard-3 receipt through the V389
            # lifecycle rebind; it cited schema-9's lifecycle digest.
            source_guard["lifecycle_sha256"] = st[
                "_v389_capital_transition"]["source_lifecycle_sha256"]
        if (_continuity_hash(source_guard) != value["source_guard_sha256"]
                or value["external_count"] != 0
                or value["external_sha256"] != _continuity_hash([])
                or value["unauthorized_trade_count"] != 0
                or value["unauthorized_trade_sha256"] !=
                    _continuity_hash([])):
            return False
    if st is None:
        return True
    binding = st.get("_lifecycle_binding") if isinstance(st, dict) else None
    identity = st.get("mt5_identity") if isinstance(st, dict) else None
    valid = bool(
        (_valid_lifecycle_binding(binding)
         or _valid_full_virtual_lifecycle_binding(binding))
        and isinstance(identity, dict)
        and identity.get("login") == value["login"] == binding["login"]
        and identity.get("server") == value["server"] == binding["server"]
        and value["lifecycle_sha256"]
            == _supported_lifecycle_binding_sha256(binding))
    if not valid:
        return False
    if schema == _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA:
        txn = st.get("_predecessor_takeover")
        inventory_txn = txn
        transition = st.get("_v389_capital_transition")
        if (_valid_lifecycle_binding(binding)
                and isinstance(transition, dict)
                and isinstance(txn, dict)
                and _valid_v389_capital_transition(transition, txn, st)
                and transition.get("prior_takeover_sha256") is not None):
            inventory_txn = copy.deepcopy(txn)
            inventory_txn["target_lifecycle_sha256"] = transition[
                "source_lifecycle_sha256"]
        return bool(
            isinstance(txn, dict)
            and txn.get("source_schema") ==
                _V383_LIFECYCLE_BINDING_SCHEMA
            and txn.get("order_intents") == []
            and txn.get("close_intents") == []
            and txn.get("source_orders") == []
            and isinstance(txn.get("source_balance_cents"), int)
            and not isinstance(txn.get("source_balance_cents"), bool)
            and value["history_start_epoch"] ==
                _cashflow_history_start_epoch(
                    st, predecessor_migration=True)
            and value["baseline_balance_cents"] ==
                txn.get("source_balance_cents")
            and txn.get("source_balance_cents") ==
                txn.get("observed_start_cents")
                + value["baseline_history_cash_cents"]
            and value["policy_sha256"] ==
                (_external_cashflow_type_policy() or {}).get("sha256")
            and _qualified_cashflow_exact_incident_shape(st)
            and value["qualified_takeover_started_msc"] ==
                int(round(float(txn.get("started_at", 0.0)) * 1000.0))
            and value["takeover_inventory_sha256"] ==
                _qualified_takeover_inventory_sha256(inventory_txn))
    return True


def _valid_clock_hold_dip(value, st=None):
    """Validate an undated conservative dip captured without rail time."""
    keys = {
        "schema", "login", "server", "lifecycle_sha256",
        "cashflow_guard_sha256", "anchor_cents", "denominator_cents",
        "applied_L", "min_equity_cents", "sess_dip", "capture_count",
    }
    if (not isinstance(value, dict) or set(value) != keys
            or value.get("schema") != _CLOCK_HOLD_DIP_SCHEMA
            or not isinstance(value.get("login"), int)
            or isinstance(value.get("login"), bool)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or not _lower_hex64(value.get("cashflow_guard_sha256"))
            or any(isinstance(value.get(key), bool)
                   or not isinstance(value.get(key), int)
                   for key in ("anchor_cents", "denominator_cents",
                               "min_equity_cents", "capture_count"))
            or value.get("anchor_cents", 0) <= 0
            or value.get("denominator_cents", 0) <= 0
            or value.get("min_equity_cents", 0) <= 0
            or not 1 <= value.get("capture_count", 0) <= 10_000_000
            or not _finite_num(value.get("applied_L"), positive=True)
            or not 0.05 < float(value["applied_L"]) <= MAX_LEVERAGE
            or not _finite_num(value.get("sess_dip"))
            or not -1.0 <= float(value["sess_dip"]) <= 0.0):
        return False
    expected = min(
        0.0,
        (value["min_equity_cents"] - value["anchor_cents"])
        / float(value["denominator_cents"])) / float(value["applied_L"])
    if not math.isclose(float(value["sess_dip"]), expected,
                        rel_tol=0.0, abs_tol=1e-12):
        return False
    if st is None:
        return True
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    identity = st.get("mt5_identity")
    guard = st.get("_external_cashflow_guard")
    if (not (_valid_lifecycle_binding(binding)
             or _valid_full_virtual_lifecycle_binding(binding))
            or not _valid_external_cashflow_guard(guard, st)
            or not isinstance(identity, dict)):
        return False
    expected_denominator = _economic_mark_cents(
        value["anchor_cents"], st)
    return bool(
        value["lifecycle_sha256"] == _lifecycle_binding_sha256(binding)
        and value["cashflow_guard_sha256"] == _continuity_hash(guard)
        and value["login"] == identity.get("login") == binding["login"]
        and value["server"] == identity.get("server") == binding["server"]
        and value["denominator_cents"] == expected_denominator)


def _valid_cfd_outage_lease(value, st=None):
    """Validate the durable late-reopen rail lease.

    The expiry is fixed relative to the scheduled reopen, never relative to
    process boot.  Identity and lifecycle binding prevent a copied state file
    from lending its rail clock to another account.
    """
    keys = {
        "schema", "lease_date", "login", "server", "lifecycle_sha256",
        "mode", "offset_s", "reopen_epoch", "expires_epoch",
        "proved_rail_date", "proved_anchor_cents",
    }
    if not isinstance(value, dict) or set(value) != keys:
        return False
    try:
        lease_date = date.fromisoformat(value.get("lease_date"))
        rail_date = date.fromisoformat(value.get("proved_rail_date"))
    except Exception:
        return False
    mode = value.get("mode")
    offset_s = value.get("offset_s")
    reopen = value.get("reopen_epoch")
    expires = value.get("expires_epoch")
    if (value.get("schema") != _CFD_OUTAGE_LEASE_SCHEMA
            or lease_date.isoformat() != value.get("lease_date")
            or rail_date.isoformat() != value.get("proved_rail_date")
            or not isinstance(value.get("login"), int)
            or isinstance(value.get("login"), bool)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or mode not in {"raw-utc", "oanda-ny17"}
            or not isinstance(offset_s, int) or isinstance(offset_s, bool)
            or (mode == "raw-utc" and offset_s != 0)
            or (mode == "oanda-ny17"
                and offset_s not in _OANDA_SERVER_OFFSETS_S)
            or not _finite_num(reopen, positive=True)
            or not _finite_num(expires, positive=True)
            or not math.isclose(float(expires) - float(reopen),
                                float(_OANDA_CFD_OUTAGE_MAX_S),
                                rel_tol=0.0, abs_tol=1e-6)
            or isinstance(value.get("proved_anchor_cents"), bool)
            or not isinstance(value.get("proved_anchor_cents"), int)
            or value.get("proved_anchor_cents", 0) <= 0):
        return False
    try:
        expected_reopen = datetime(
            lease_date.year, lease_date.month, lease_date.day,
            _OANDA_CFD_REOPEN_MIN // 60,
            _OANDA_CFD_REOPEN_MIN % 60, tzinfo=NY).timestamp()
    except Exception:
        return False
    if not math.isclose(float(reopen), expected_reopen,
                        rel_tol=0.0, abs_tol=1e-6):
        return False
    if st is None:
        return True
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    identity = st.get("mt5_identity")
    return bool(
        _valid_full_virtual_lifecycle_binding(binding)
        and _lifecycle_binding_sha256(binding) == value["lifecycle_sha256"]
        and isinstance(identity, dict)
        and identity.get("login") == value["login"] == binding.get("login")
        and identity.get("server") == value["server"] == binding.get("server"))


def _valid_short_session_lease(value, st=None):
    """Validate a pre-cut, account-bound scheduled NAS half-day lease."""
    keys = {
        "schema", "session", "login", "server", "lifecycle_sha256",
        "mode", "offset_s", "armed_epoch", "cutoff_epoch",
        "expires_epoch", "proved_rail_date", "proved_anchor_cents",
    }
    if not isinstance(value, dict) or set(value) != keys:
        return False
    try:
        session = date.fromisoformat(value.get("session"))
        cutoff = datetime(
            session.year, session.month, session.day,
            _SHORT_SESSION_CUTOFF_MIN // 60,
            _SHORT_SESSION_CUTOFF_MIN % 60, tzinfo=NY).timestamp()
        expires = datetime(
            session.year, session.month, session.day,
            _SHORT_SESSION_EXPIRY_MIN // 60,
            _SHORT_SESSION_EXPIRY_MIN % 60, tzinfo=NY).timestamp()
        rail_date = date.fromisoformat(value.get("proved_rail_date"))
    except Exception:
        return False
    mode = value.get("mode")
    offset_s = value.get("offset_s")
    if (value.get("schema") != _SHORT_SESSION_LEASE_SCHEMA
            or session.isoformat() != value.get("session")
            or not _nas_orb_early_close_ord(session.toordinal())
            or rail_date.isoformat() != value.get("proved_rail_date")
            or not isinstance(value.get("login"), int)
            or isinstance(value.get("login"), bool)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or mode not in {"raw-utc", "oanda-ny17"}
            or not isinstance(offset_s, int) or isinstance(offset_s, bool)
            or (mode == "raw-utc" and offset_s != 0)
            or (mode == "oanda-ny17"
                and offset_s not in _OANDA_SERVER_OFFSETS_S)
            or not _finite_num(value.get("armed_epoch"), positive=True)
            or not _finite_num(value.get("cutoff_epoch"), positive=True)
            or not _finite_num(value.get("expires_epoch"), positive=True)
            or not math.isclose(float(value["cutoff_epoch"]), cutoff,
                                rel_tol=0.0, abs_tol=1e-6)
            or not math.isclose(float(value["expires_epoch"]), expires,
                                rel_tol=0.0, abs_tol=1e-6)
            or not (float(value["armed_epoch"]) < cutoff < expires)
            or isinstance(value.get("proved_anchor_cents"), bool)
            or not isinstance(value.get("proved_anchor_cents"), int)
            or value.get("proved_anchor_cents", 0) <= 0):
        return False
    if st is None:
        return True
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    identity = st.get("mt5_identity")
    return bool(
        _valid_full_virtual_lifecycle_binding(binding)
        and _lifecycle_binding_sha256(binding) == value["lifecycle_sha256"]
        and isinstance(identity, dict)
        and identity.get("login") == value["login"] == binding.get("login")
        and identity.get("server") == value["server"] == binding.get("server"))


def _valid_unleased_reopen_guard(value, st=None):
    """Validate loaded-state recovery after booting inside a CFD closure."""
    common_keys = {
        "schema", "closure_date", "login", "server", "lifecycle_sha256",
        "reopen_epoch", "status", "sample_count", "last_nas_tick",
        "last_xau_tick", "not_before_epoch",
    }
    if not isinstance(value, dict):
        return False
    schema = value.get("schema")
    predecessor = schema == _PREDECESSOR_UNLEASED_REOPEN_GUARD_SCHEMA
    if schema == _UNLEASED_REOPEN_GUARD_SCHEMA:
        expected_keys = common_keys | {"last_btc_tick"}
    elif predecessor:
        expected_keys = common_keys
    else:
        return False
    if set(value) != expected_keys:
        return False
    try:
        closure = date.fromisoformat(value.get("closure_date"))
        reopen = datetime(
            closure.year, closure.month, closure.day,
            _OANDA_CFD_REOPEN_MIN // 60,
            _OANDA_CFD_REOPEN_MIN % 60, tzinfo=NY).timestamp()
    except Exception:
        return False
    count = value.get("sample_count")
    status = value.get("status")
    nas_tick = value.get("last_nas_tick")
    xau_tick = value.get("last_xau_tick")
    btc_tick = (None if predecessor else value.get("last_btc_tick"))
    saved_ticks = ((nas_tick, xau_tick) if predecessor else
                   (nas_tick, xau_tick, btc_tick))
    if (closure.isoformat() != value.get("closure_date")
            or closure.weekday() not in {0, 1, 2, 3, 6}
            or not isinstance(value.get("login"), int)
            or isinstance(value.get("login"), bool)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or not _finite_num(value.get("reopen_epoch"), positive=True)
            or not math.isclose(float(value["reopen_epoch"]), reopen,
                                rel_tol=0.0, abs_tol=1e-6)
            or status not in {"WAIT_SAMPLES", "COOLDOWN"}
            or isinstance(count, bool) or not isinstance(count, int)
            or not 0 <= count <= _CFD_REOPEN_GOOD_SAMPLES
            or any(isinstance(raw, bool) or not isinstance(raw, int)
                   or raw < 0 for raw in saved_ticks)
            or (count == 0 and any(raw != 0 for raw in saved_ticks))
            or (count > 0 and any(raw <= 0 for raw in saved_ticks))
            or (status == "WAIT_SAMPLES"
                and count >= _CFD_REOPEN_GOOD_SAMPLES)
            or (status == "COOLDOWN"
                and count != _CFD_REOPEN_GOOD_SAMPLES)
            or not _finite_num(value.get("not_before_epoch"), positive=True)
            or float(value["not_before_epoch"])
                < reopen + _CFD_REOPEN_COOLDOWN_S - 1e-9):
        return False
    if st is None:
        return True
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    identity = st.get("mt5_identity")
    return bool(
        _valid_full_virtual_lifecycle_binding(binding)
        and value["lifecycle_sha256"] == _lifecycle_binding_sha256(binding)
        and isinstance(identity, dict)
        and value["login"] == identity.get("login") == binding["login"]
        and value["server"] == identity.get("server") == binding["server"])


def _valid_reopen_entry_guard(value, st=None):
    keys = {
        "schema", "lease_date", "login", "server", "lifecycle_sha256",
        "recovered_epoch", "not_before_epoch",
    }
    if not isinstance(value, dict) or set(value) != keys:
        return False
    try:
        lease_date = date.fromisoformat(value.get("lease_date"))
    except Exception:
        return False
    recovered = value.get("recovered_epoch")
    not_before = value.get("not_before_epoch")
    if (value.get("schema") != _REOPEN_ENTRY_GUARD_SCHEMA
            or lease_date.isoformat() != value.get("lease_date")
            or not isinstance(value.get("login"), int)
            or isinstance(value.get("login"), bool)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or not _finite_num(recovered, positive=True)
            or not _finite_num(not_before, positive=True)
            or not math.isclose(
                float(not_before) - float(recovered),
                _CFD_REOPEN_COOLDOWN_S, rel_tol=0.0, abs_tol=1e-6)):
        return False
    if st is None:
        return True
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    identity = st.get("mt5_identity")
    return bool(
        _valid_lifecycle_binding(binding)
        and _lifecycle_binding_sha256(binding) == value["lifecycle_sha256"]
        and isinstance(identity, dict)
        and identity.get("login") == value["login"] == binding.get("login")
        and identity.get("server") == value["server"] == binding.get("server"))


def _valid_daily_entry_plan(value):
    keys = {
        "schema", "session", "symbol", "magic", "target_signed_lots",
        "first_eval_epoch", "expires_epoch",
    }
    if not isinstance(value, dict) or set(value) != keys:
        return False
    first = value.get("first_eval_epoch")
    expires = value.get("expires_epoch")
    magic = value.get("magic")
    return bool(
        value.get("schema") == _DAILY_ENTRY_PLAN_SCHEMA
        and _continuity_session(value.get("session")) is not None
        and isinstance(value.get("symbol"), str)
        and isinstance(magic, int) and not isinstance(magic, bool)
        and _expected_symbol_for_magic(magic) == value.get("symbol")
        and magic != MAGIC.get("ORB")
        and _finite_num(value.get("target_signed_lots"))
        and _finite_num(first, positive=True)
        and _finite_num(expires, positive=True)
        and float(first) <= float(expires)
        and float(expires) - float(first) <= 30.0 * 60.0 + 1e-6)


def _valid_daily_entry_plan_book(value):
    if (not isinstance(value, dict)
            or set(value) != {"schema", "plans"}
            or value.get("schema") != _DAILY_ENTRY_PLAN_BOOK_SCHEMA
            or not isinstance(value.get("plans"), dict)
            or len(value["plans"]) > 8):
        return False
    for key, plan in value["plans"].items():
        if (not isinstance(key, str) or not key.isdecimal()
                or key != str(int(key))
                or not _valid_daily_entry_plan(plan)
                or int(key) != plan["magic"]):
            return False
    return True


def _valid_ledger_bootstrap(value, st=None):
    """Bind an unfinished first-start ledger initialization to one lifecycle."""
    if not isinstance(value, dict):
        return False
    schema = value.get("schema")
    legacy = schema == _LEGACY_LEDGER_BOOTSTRAP_SCHEMA
    recipe = value.get("recipe")
    fresh_history_recipe = recipe in {
        "p1", "p2-fresh", "p2-adopt", "p2-standalone-immediate"}
    keys = {"schema", "recipe", "lifecycle_sha256", "start_cents"}
    if not legacy:
        keys.add("history_baseline")
    if (set(value) != keys
            or schema not in {
                _LEGACY_LEDGER_BOOTSTRAP_SCHEMA, _LEDGER_BOOTSTRAP_SCHEMA}
            or (not legacy and not _valid_fresh_history_baseline(
                value.get("history_baseline")))
            or (not legacy and not fresh_history_recipe)
            or recipe not in {
                "p1", "p2-fresh", "p2-adopt",
                "p2-standalone-immediate", "funded"}
            or not _lower_hex64(value.get("lifecycle_sha256"))
            or isinstance(value.get("start_cents"), bool)
            or not isinstance(value.get("start_cents"), int)
            or value.get("start_cents", 0) <= 0):
        return False
    if st is None:
        return True
    binding = st.get("_lifecycle_binding") if isinstance(st, dict) else None
    return bool(
        _valid_lifecycle_binding(binding)
        and value["recipe"] == binding["recipe"]
        and value["start_cents"] == binding["observed_start_cents"]
        and value["lifecycle_sha256"] == _lifecycle_binding_sha256(binding))


def _valid_close_intent_record(x):
    """Validate one exact-ticket close authority without side effects."""
    allowed = {
        "schema", "status", "symbol", "magic", "ticket",
        "position_side", "pre_volume", "close_volume", "purpose",
        "comment", "token", "sent_at", "tick_at_send", "detail",
        "ack_order", "ack_deal", "ack_request_id", "ack_retcode", "scope",
        "fill_mode", "request_price", "deviation", "type_time",
        "position_identifier",
    }
    if not isinstance(x, dict) or set(x) - allowed:
        return False
    status = x.get("status")
    owned_scope = bool(
        x.get("schema") == _CLOSE_INTENT_SCHEMA
        and "scope" not in x
        and _expected_symbol_for_magic(x.get("magic")) == x.get("symbol"))
    account_scope = bool(
        x.get("schema") == _ACCOUNT_CLOSE_INTENT_SCHEMA
        and x.get("scope") == "account")
    ok = ((owned_scope or account_scope)
          and isinstance(status, str)
          and status in {"PREPARED", "UNKNOWN_RESPONSE", "ACK_PENDING",
                         "ACK_REJECTED"}
          and isinstance(x.get("symbol"), str) and bool(x.get("symbol"))
          and isinstance(x.get("magic"), int)
          and not isinstance(x.get("magic"), bool)
          and 0 <= x.get("magic", -1) <= _MAX_MT5_TICKET
          and isinstance(x.get("ticket"), int)
          and not isinstance(x.get("ticket"), bool)
          and 0 < x.get("ticket", 0) <= _MAX_MT5_TICKET
          and x.get("position_side") in ("buy", "sell")
          and _finite_num(x.get("pre_volume"), positive=True)
          and _finite_num(x.get("close_volume"), positive=True)
          and float(x["close_volume"]) <= float(x["pre_volume"]) + 1e-9
          and isinstance(x.get("purpose"), str) and bool(x.get("purpose"))
          and isinstance(x.get("comment"), str)
          and isinstance(x.get("token"), str)
          and 4 <= len(x.get("token", "")) <= 30
          and _finite_num(x.get("sent_at"), positive=True)
          and isinstance(x.get("tick_at_send"), int)
          and not isinstance(x.get("tick_at_send"), bool)
          and x.get("tick_at_send", -1) >= 0)
    if not ok:
        return False
    for key in ("ack_order", "ack_deal", "ack_request_id", "ack_retcode"):
        if key in x and not (isinstance(x[key], int)
                             and not isinstance(x[key], bool)
                             and x[key] >= 0):
            return False
    if ("position_identifier" in x
            and (isinstance(x["position_identifier"], bool)
                 or not isinstance(x["position_identifier"], int)
                 or not 0 < x["position_identifier"] <= _MAX_MT5_TICKET)):
        return False
    if ("fill_mode" in x
            and (isinstance(x["fill_mode"], bool)
                 or not isinstance(x["fill_mode"], int)
                 or x["fill_mode"] < 0)):
        return False
    request_fields = {"request_price", "deviation", "type_time"}
    present_request_fields = request_fields.intersection(x)
    if present_request_fields and (
            present_request_fields != request_fields
            or not _finite_num(x.get("request_price"), positive=True)
            or isinstance(x.get("deviation"), bool)
            or not isinstance(x.get("deviation"), int)
            or not 0 <= x.get("deviation", -1) <= 10_000
            or isinstance(x.get("type_time"), bool)
            or not isinstance(x.get("type_time"), int)
            or x.get("type_time", -1) < 0):
        return False
    if (status == "ACK_REJECTED"
            and (x.get("ack_retcode") not in _EXPLICIT_REJECT_RETCODES
                 or int(x.get("ack_order", 0) or 0) != 0
                 or int(x.get("ack_deal", 0) or 0) != 0)):
        return False
    return "detail" not in x or isinstance(x["detail"], str)


def _close_intent_records(st):
    """Return ticket->record for valid legacy/book authority; None if bad."""
    if not isinstance(st, dict):
        return None
    if "_close_intent" not in st:
        return {}
    raw = st.get("_close_intent")
    if _valid_close_intent_record(raw):
        return {int(raw["ticket"]): raw}
    if (not isinstance(raw, dict)
            or set(raw) != {"schema", "intents"}
            or raw.get("schema") != _CLOSE_INTENT_BOOK_SCHEMA
            or not isinstance(raw.get("intents"), dict)
            or not raw["intents"] or len(raw["intents"]) > 128):
        return None
    records = {}
    tokens = set()
    identifiers = set()
    for key, record in raw["intents"].items():
        if (not isinstance(key, str) or not 1 <= len(key) <= 20
                or not key.isascii() or not key.isdecimal()
                or key != str(int(key)) or not _valid_close_intent_record(record)
                or key != str(record["ticket"])):
            return None
        identifier = record.get("position_identifier")
        if (record["ticket"] in records
                or record["token"] in tokens
                or (identifier is not None and identifier in identifiers)):
            return None
        records[record["ticket"]] = record
        tokens.add(record["token"])
        if identifier is not None:
            identifiers.add(identifier)
    return records


def _valid_close_intent_authority(value):
    probe = {"_close_intent": value}
    records = _close_intent_records(probe)
    return records is not None and bool(records)


def _valid_prague_anchor_proof(value, st):
    """Validate the durable proof required for any exposure increase."""
    if not isinstance(value, dict) or not isinstance(st, dict):
        return False
    br = st.get("breaker")
    binding = st.get("_lifecycle_binding")
    if not isinstance(br, dict) or not isinstance(binding, dict):
        return False
    common = {
        "schema", "kind", "date", "login", "server", "currency",
        "midnight_balance_cents", "anchor_cents",
    }
    kind = value.get("kind")
    expected = (
        common | {
            "flat_balance_cents", "prior_anchor_cents",
            "history_mode", "trade_deal_count",
            "closed_position_count", "trade_history_sha256",
        } if kind == "flat-rebase" else
        common | {
            "pre_balance_cents", "pre_equity_cents",
            "post_balance_cents", "post_equity_cents",
        } if kind == "paired-rollover" else
        common | {
            "current_balance_cents", "prior_anchor_cents",
            "history_mode", "trade_deal_count",
            "closed_position_count", "open_position_count",
            "cash_deal_count", "cash_history_sha256",
            "trade_history_sha256", "cashflow_guard_sha256",
            "takeover_inventory_sha256", "anchor_receipt_sha256",
        } if kind == "qualified-takeover-midnight-flat" else
        common | {
            "current_balance_cents", "prior_anchor_cents",
            "cash_deal_count", "cash_history_sha256",
            "cashflow_guard_sha256", "takeover_inventory_sha256",
            "anchor_receipt_sha256",
        } if kind == "reconstructed-takeover-midnight-balance" else None)
    if expected is None or set(value) != expected:
        return False
    try:
        canonical_date = date.fromisoformat(value.get("date")).isoformat()
    except Exception:
        return False
    metadata_keys = {
        "schema", "kind", "date", "login", "server", "currency",
        "history_mode", "trade_deal_count", "closed_position_count",
        "open_position_count", "cash_deal_count", "cash_history_sha256",
        "trade_history_sha256",
        "cashflow_guard_sha256", "takeover_inventory_sha256",
        "anchor_receipt_sha256",
    }
    money_keys = expected - metadata_keys
    proof_schema = value.get("schema")
    if (proof_schema not in {
                _PRAGUE_ANCHOR_PROOF_SCHEMA,
                _LEGACY_PRAGUE_ANCHOR_PROOF_SCHEMA}
            or (kind == "qualified-takeover-midnight-flat"
                and proof_schema != _PRAGUE_ANCHOR_PROOF_SCHEMA)
            or (kind == "reconstructed-takeover-midnight-balance"
                and proof_schema != _PRAGUE_ANCHOR_PROOF_SCHEMA)
            or canonical_date != value.get("date")
            or value.get("date") != br.get("date")
            or value.get("login") != binding.get("login")
            or value.get("server") != binding.get("server")
            or value.get("currency") != "USD"
            or any(isinstance(value.get(key), bool)
                   or not isinstance(value.get(key), int)
                   or value.get(key) <= 0 for key in money_keys)):
        return False
    if kind == "flat-rebase":
        history_mode = value.get("history_mode")
        deal_count = value.get("trade_deal_count")
        position_count = value.get("closed_position_count")
        # V387's schema-2 receipt called an empty narrow Prague-day query
        # ``clean-lifetime``.  Preserve already-persisted receipts, but V388
        # may make that claim only as the accurately named current-day mode
        # after a stable broad-history/current-day-suffix equality proof.
        clean_lifetime = bool(
            history_mode == "clean-lifetime"
            and proof_schema == _LEGACY_PRAGUE_ANCHOR_PROOF_SCHEMA)
        clean_current_day = bool(
            history_mode == "clean-current-day"
            and proof_schema == _PRAGUE_ANCHOR_PROOF_SCHEMA)
        closed_same_day = history_mode == "closed-current-day-lifecycles"
        if (not (clean_lifetime or clean_current_day or closed_same_day)
                or isinstance(deal_count, bool)
                or not isinstance(deal_count, int) or deal_count < 0
                or isinstance(position_count, bool)
                or not isinstance(position_count, int) or position_count < 0
                or not _lower_hex64(value.get("trade_history_sha256"))
                or ((clean_lifetime or clean_current_day)
                    and (deal_count != 0 or position_count != 0))
                or (closed_same_day
                    and (position_count <= 0
                         or deal_count < 2 * position_count))):
            return False
    elif kind == "qualified-takeover-midnight-flat":
        guard = st.get("_external_cashflow_guard")
        txn = st.get("_predecessor_takeover")
        deal_count = value.get("trade_deal_count")
        cash_count = value.get("cash_deal_count")
        closed_count = value.get("closed_position_count")
        open_count = value.get("open_position_count")
        if (value.get("history_mode") !=
                "qualified-takeover-midnight-flat"
                or any(isinstance(count, bool) or not isinstance(count, int)
                       or count < 0
                       for count in (
                           deal_count, cash_count, closed_count, open_count))
                or deal_count < open_count
                or cash_count < deal_count
                or closed_count + open_count > 4096
                or not _lower_hex64(value.get("trade_history_sha256"))
                or not _lower_hex64(value.get("cash_history_sha256"))
                or not _lower_hex64(value.get("cashflow_guard_sha256"))
                or not _lower_hex64(value.get(
                    "takeover_inventory_sha256"))
                or not _lower_hex64(value.get("anchor_receipt_sha256"))
                or not _valid_external_cashflow_guard(guard, st)
                or guard.get("schema") !=
                    _QUALIFIED_EXTERNAL_CASHFLOW_GUARD_SCHEMA
                or value["cashflow_guard_sha256"] !=
                    _continuity_hash(guard)
                or not _valid_predecessor_takeover_txn(txn, st)
                or not _qualified_cashflow_exact_incident_shape(st)
                or not _qualified_current_inventory_is_source_reduction(txn)
                or value["takeover_inventory_sha256"] !=
                    _qualified_takeover_current_inventory_sha256(txn)):
            return False
        receipt_payload = dict(value)
        receipt_sha = receipt_payload.pop("anchor_receipt_sha256", None)
        expected_receipt_sha = _continuity_hash({
            "schema": "qualified_takeover_anchor_receipt/1",
            "proof": receipt_payload,
        })
        if (not _lower_hex64(expected_receipt_sha)
                or receipt_sha != expected_receipt_sha):
            return False
    elif kind == "reconstructed-takeover-midnight-balance":
        guard = st.get("_external_cashflow_guard")
        txn = st.get("_predecessor_takeover")
        cash_count = value.get("cash_deal_count")
        if (isinstance(cash_count, bool)
                or not isinstance(cash_count, int) or cash_count < 0
                or not _lower_hex64(value.get("cash_history_sha256"))
                or not _lower_hex64(value.get("cashflow_guard_sha256"))
                or not _lower_hex64(value.get(
                    "takeover_inventory_sha256"))
                or not _lower_hex64(value.get("anchor_receipt_sha256"))
                or not _valid_external_cashflow_guard(guard, st)
                or value["cashflow_guard_sha256"] !=
                    _continuity_hash(guard)
                or not _valid_predecessor_takeover_txn(txn, st)
                or not _qualified_current_inventory_is_source_reduction(txn)
                or value["takeover_inventory_sha256"] !=
                    _qualified_takeover_current_inventory_sha256(txn)):
            return False
        receipt_payload = dict(value)
        receipt_sha = receipt_payload.pop("anchor_receipt_sha256", None)
        expected_receipt_sha = _continuity_hash({
            "schema": "v389_reconstructed_takeover_anchor_receipt/1",
            "proof": receipt_payload,
        })
        if (not _lower_hex64(expected_receipt_sha)
                or receipt_sha != expected_receipt_sha):
            return False
    if (not _finite_num(br.get("anchor"), positive=True)
            or abs(float(br["anchor"])
                   - value["anchor_cents"] / 100.0) > 1e-6):
        return False
    if kind == "flat-rebase":
        expected_anchor = max(
            value["midnight_balance_cents"], value["flat_balance_cents"],
            value["prior_anchor_cents"])
    elif kind in {"qualified-takeover-midnight-flat",
                  "reconstructed-takeover-midnight-balance"}:
        expected_anchor = max(
            value["midnight_balance_cents"],
            value["current_balance_cents"],
            value["prior_anchor_cents"])
    else:
        expected_anchor = max(
            value["midnight_balance_cents"],
            value["pre_balance_cents"], value["pre_equity_cents"],
            value["post_balance_cents"], value["post_equity_cents"])
    return bool(value["anchor_cents"] == expected_anchor
                and br.get("cold_start") is False)


def _pending_close_tickets(st):
    records = _close_intent_records(st)
    return None if records is None else frozenset(records)


def _pending_close_identifiers(st):
    records = _close_intent_records(st)
    if records is None:
        return None
    return frozenset(
        record["position_identifier"] for record in records.values()
        if "position_identifier" in record)


def _validate_safety_records_impl(
        st, log_bad=False, allow_target_ledger_quarantine=False,
        allow_target_missing_handoff=False):
    """Strictly validate durable records that control permission to trade.

    Presence is authoritative: malformed records are never dropped or treated
    as absent.  They leave the process alive for account rails but block every
    exposure-increasing path until manually repaired from broker evidence.
    """
    problems = []
    ledger_quarantine_ok = False
    if not isinstance(st, dict):
        problems.append("runtime state is not an object")
    else:
        if (allow_target_ledger_quarantine
                or allow_target_missing_handoff):
            watch = st.get("_target_flat_watch")
            hit = st.get("_target_hit")
            post = st.get("_post_hit_catchup")
            # Before HIT, an exact current watch owns a permanent NNR/flatten
            # path and may carry the raw invalid ledger preimage into the
            # atomic audit marker.  After HIT, waiver requires that marker to
            # validate and hash-match the untouched evidence.  No other safety
            # error is waived, and ordinary ledger/export callers never set
            # this option.
            ledger_quarantine_ok = bool(
                _valid_current_target_watch_impl(watch, st)
                or (_valid_target_hit(hit, st)
                    and isinstance(post, dict)
                    and post.get("stage") == "AUDIT_REQUIRED"
                    and _valid_post_hit_catchup(post, st)))
            # Narrow startup bridge for a crash/migration image whose exact HIT
            # survived but whose handoff marker did not.  Only lifecycle startup
            # passes this flag; the terminal service must re-prove flat cash,
            # mint the missing audit/export marker, and rotate it through both
            # images before the ordinary strict recovery-pair proof can pass.
            if allow_target_missing_handoff:
                ledger_quarantine_ok = bool(
                    ledger_quarantine_ok
                    or (_valid_target_hit(hit, st)
                        and "_post_hit_catchup" not in st
                        and "_continuity_export_txn" not in st))
        _safety_binding = st.get("_lifecycle_binding")
        _predecessor_terminal_binding = bool(
            _valid_predecessor_terminal_custody_binding(_safety_binding)
            and any(key in st for key in _V382_TERMINAL_MIGRATION_KEYS))
        if ("_lifecycle_binding" in st
                and not (_valid_lifecycle_binding(_safety_binding)
                         or _predecessor_terminal_binding)):
            problems.append("_lifecycle_binding malformed/conflicting")
        if ("_controller_ledger" in st
                and not _valid_controller_ledger(
                    st.get("_controller_ledger"))):
            problems.append("_controller_ledger malformed/conflicting")
        if ("_r4_migration" in st
                and not _valid_r4_migration(st.get("_r4_migration"), st)):
            problems.append("_r4_migration malformed/conflicting")
        if ("_pause_new_risk" in st
                and not _valid_pause_new_risk(st.get("_pause_new_risk"))):
            problems.append("_pause_new_risk malformed/conflicting")
        if ("_applied_exposure" in st
                and not _valid_applied_exposure(
                    st.get("_applied_exposure"))):
            problems.append("_applied_exposure malformed/conflicting")
        if ("_predecessor_takeover" in st
                and not _valid_predecessor_takeover_txn(
                    st.get("_predecessor_takeover"), st)):
            problems.append("_predecessor_takeover malformed/conflicting")
        if ("_v389_capital_transition" in st
                and not _valid_v389_capital_transition(
                    st.get("_v389_capital_transition"),
                    st.get("_predecessor_takeover"), st)):
            problems.append("_v389_capital_transition malformed/conflicting")
        if ("_takeover_applied_scale" in st
                and not _valid_takeover_applied_scale(
                    st.get("_takeover_applied_scale"), st)):
            problems.append("_takeover_applied_scale malformed/conflicting")
        if (_takeover_applied_scale_required(st)
                and "_takeover_applied_scale" not in st):
            problems.append("_takeover_applied_scale missing")
        if ("_takeover_orb_scale_receipt" in st
                and not _valid_takeover_orb_scale_receipt(
                    st.get("_takeover_orb_scale_receipt"), st)):
            problems.append("_takeover_orb_scale_receipt malformed/conflicting")
        if ("_external_cashflow_guard" in st
                and not _valid_external_cashflow_guard(
                    st.get("_external_cashflow_guard"), st)):
            problems.append(
                "_external_cashflow_guard malformed/conflicting")
        if ("_clock_hold_dip" in st
                and not _valid_clock_hold_dip(
                    st.get("_clock_hold_dip"), st)):
            problems.append("_clock_hold_dip malformed/conflicting")
        br = st.get("breaker")
        if (isinstance(br, dict) and "anchor_proof" in br
                and not _valid_prague_anchor_proof(
                    br.get("anchor_proof"), st)):
            problems.append("breaker.anchor_proof malformed/conflicting")
        if ("_cfd_outage_lease" in st
                and not _valid_cfd_outage_lease(
                    st.get("_cfd_outage_lease"), st)):
            problems.append("_cfd_outage_lease malformed/conflicting")
        if ("_short_session_lease" in st
                and not _valid_short_session_lease(
                    st.get("_short_session_lease"), st)):
            problems.append("_short_session_lease malformed/conflicting")
        if ("_unleased_reopen_guard" in st
                and not _valid_unleased_reopen_guard(
                    st.get("_unleased_reopen_guard"), st)):
            problems.append("_unleased_reopen_guard malformed/conflicting")
        if ("_reopen_entry_guard" in st
                and not _valid_reopen_entry_guard(
                    st.get("_reopen_entry_guard"), st)):
            problems.append("_reopen_entry_guard malformed/conflicting")
        if ("_daily_entry_plan" in st
                and not _valid_daily_entry_plan_book(
                    st.get("_daily_entry_plan"))):
            problems.append("_daily_entry_plan malformed/conflicting")
        if "_order_intent" in st:
            x = st.get("_order_intent")
            allowed = {
                "schema", "status", "symbol", "magic", "side", "volume",
                "purpose", "comment", "token", "sent_at", "pre",
                "tick_at_send", "confirmations", "detail", "ack_order",
                "ack_deal", "ack_request_id", "ack_retcode", "order",
                "deal", "request_id", "effect",
                "fill_mode", "execution",
            }
            ok = isinstance(x, dict)
            if ok:
                status = x.get("status")
                ok = not (set(x) - allowed)
                ok = ok and x.get("schema") == _ORDER_INTENT_SCHEMA
                ok = (ok and isinstance(status, str) and status in {
                    "PREPARED", "UNKNOWN_RESPONSE", "ACK_PENDING",
                    "ACK_REJECTED"})
                ok = (ok and isinstance(x.get("symbol"), str)
                      and bool(x.get("symbol")))
                ok = (ok and isinstance(x.get("magic"), int)
                      and not isinstance(x.get("magic"), bool))
                if isinstance(x.get("magic"), int):
                    ok = (ok and not isinstance(x.get("magic"), bool)
                          and _expected_symbol_for_magic(x["magic"])
                          == x.get("symbol"))
                ok = ok and x.get("side") in ("buy", "sell")
                ok = ok and _finite_num(x.get("volume"), positive=True)
                ok = ok and isinstance(x.get("purpose"), str)
                ok = ok and isinstance(x.get("comment"), str)
                ok = (ok and isinstance(x.get("token"), str)
                      and 4 <= len(x.get("token", "")) <= 30)
                ok = ok and _finite_num(x.get("sent_at"), positive=True)
                ok = (ok and isinstance(x.get("tick_at_send"), int)
                      and not isinstance(x.get("tick_at_send"), bool)
                      and x.get("tick_at_send") >= 0)
                ok = (ok and isinstance(x.get("confirmations"), int)
                      and not isinstance(x.get("confirmations"), bool)
                      and x.get("confirmations") >= 0)
                pre = x.get("pre")
                ok = ok and isinstance(pre, dict) and set(pre) == {
                    "rows", "signed"}
                if isinstance(pre, dict):
                    ok = ok and _finite_num(pre.get("signed"))
                    rows = pre.get("rows")
                else:
                    rows = None
                    ok = False
                ok = ok and isinstance(rows, list)
                if isinstance(rows, list):
                    for row in rows:
                        if not (isinstance(row, list) and len(row) == 4
                                and isinstance(row[0], int)
                                and not isinstance(row[0], bool)
                                and row[0] > 0
                                and isinstance(row[1], float)
                                and not isinstance(row[1], bool)
                                and row[1] in (-1.0, 1.0)
                                and _finite_num(row[2], positive=True)
                                and isinstance(row[3], str)
                                and row[3] == x.get("symbol")):
                            ok = False
                            break
                    if isinstance(rows, list):
                        tickets = [row[0] for row in rows
                                   if isinstance(row, list) and len(row) == 4]
                        recomposed = sum(float(row[1]) * float(row[2])
                                         for row in rows
                                         if isinstance(row, list)
                                         and len(row) == 4)
                        ok = (ok and rows == sorted(rows)
                              and len(tickets) == len(set(tickets))
                              and math.isclose(
                                  float(pre.get("signed", float("nan"))),
                                  recomposed, rel_tol=0.0, abs_tol=1e-12))
                for key in ("ack_order", "ack_deal", "ack_request_id",
                            "ack_retcode", "order", "deal", "request_id"):
                    if key in x and not (isinstance(x[key], int)
                                         and not isinstance(x[key], bool)
                                         and x[key] >= 0):
                        ok = False
                if ("fill_mode" in x
                        and (isinstance(x["fill_mode"], bool)
                             or not isinstance(x["fill_mode"], int)
                             or x["fill_mode"] < 0)):
                    ok = False
                if "detail" in x and not isinstance(x["detail"], str):
                    ok = False
                if "execution" in x:
                    execution = x["execution"]
                    fp = (execution.get("spec_fingerprint")
                          if isinstance(execution, dict) else None)
                    legacy_execution_keys = {
                        "spec_fingerprint", "request_price", "deviation",
                        "max_fill_price", "max_notional",
                        "latest_fill_epoch"}
                    current_execution_keys = legacy_execution_keys | {
                        "expected_existing_abs_lots",
                        "max_total_notional",
                        "projected_max_total_notional",
                        "equity_notional_fraction",
                        "equity_stop_loss_fraction"}
                    execution_keys = (frozenset(execution)
                                      if isinstance(execution, dict)
                                      else frozenset())
                    ok = (ok and isinstance(execution, dict)
                          and execution_keys in {
                              frozenset(legacy_execution_keys),
                              frozenset(current_execution_keys)}
                          and isinstance(fp, list) and len(fp) == 11
                          and isinstance(fp[0], str)
                          and fp[0] == x.get("symbol")
                          and all(_finite_num(fp[index], positive=True)
                                  for index in (1, 2, 3, 4, 5, 8))
                          and all(isinstance(fp[index], int)
                                  and not isinstance(fp[index], bool)
                                  for index in (6, 7, 9, 10))
                          and 0 <= fp[6] <= 12
                          and fp[7] >= 0 and fp[9] >= 0 and fp[10] >= 0
                          and _finite_num(execution.get("request_price"),
                                          positive=True)
                          and isinstance(execution.get("deviation"), int)
                          and not isinstance(execution.get("deviation"), bool)
                          and 0 <= execution.get("deviation", -1) <= 10_000
                          and _finite_num(execution.get("max_fill_price"),
                                          positive=True)
                          and _finite_num(execution.get("max_notional"),
                                          positive=True)
                          and _finite_num(execution.get("latest_fill_epoch"),
                                          positive=True)
                          and float(execution["latest_fill_epoch"])
                              >= float(x.get("sent_at", 0.0)) - 1e-9
                          and float(execution["latest_fill_epoch"])
                              <= float(x.get("sent_at", 0.0))
                                  + _MAX_BROKER_FILL_LATENCY_S + 1e-9)
                    if execution_keys == current_execution_keys:
                        expected_existing = execution.get(
                            "expected_existing_abs_lots")
                        total_cap = execution.get("max_total_notional")
                        projected = execution.get(
                            "projected_max_total_notional")
                        notional_fraction = execution.get(
                            "equity_notional_fraction")
                        stop_fraction = execution.get(
                            "equity_stop_loss_fraction")
                        try:
                            side_sign = (1.0 if x.get("side") == "buy"
                                         else -1.0)
                            fresh_existing = sum(
                                float(row[2]) for row in rows)
                            tolerance = max(
                                float(fp[8]),
                                int(execution["deviation"])
                                * float(fp[5]))
                            recomputed_projected = (
                                (float(expected_existing)
                                 + float(x["volume"]))
                                * float(fp[1])
                                * (float(execution["request_price"])
                                   + tolerance))
                            current_cap_ok = bool(
                                _finite_num(expected_existing)
                                and float(expected_existing) >= 0.0
                                and _finite_num(total_cap, positive=True)
                                and _finite_num(projected, positive=True)
                                and _finite_num(
                                    notional_fraction, positive=True)
                                and _finite_num(stop_fraction)
                                and float(stop_fraction) >= 0.0
                                and all(float(row[1]) == side_sign
                                        for row in rows)
                                and math.isclose(
                                    fresh_existing,
                                    float(expected_existing), rel_tol=0.0,
                                    abs_tol=max(1e-9,
                                                float(fp[4]) * 1e-7))
                                and math.isclose(
                                    float(projected), recomputed_projected,
                                    rel_tol=0.0, abs_tol=1e-8)
                                and float(projected)
                                    <= float(total_cap) + 1e-8
                                and ((isinstance(x.get("effect"), dict)
                                      and x["effect"].get("kind")
                                          == "orb_entry"
                                      and float(stop_fraction) > 0.0)
                                     or ("effect" not in x
                                         and float(stop_fraction) == 0.0)))
                        except Exception:
                            current_cap_ok = False
                        ok = ok and current_cap_ok
                if (status == "ACK_REJECTED"
                        and (x.get("ack_retcode") not in
                             _EXPLICIT_REJECT_RETCODES
                             or int(x.get("ack_order", 0) or 0) != 0
                             or int(x.get("ack_deal", 0) or 0) != 0)):
                    ok = False
                if "effect" in x:
                    eff = x["effect"]
                    if not isinstance(eff, dict):
                        ok = False
                    else:
                        legacy_keys = {"kind", "date"}
                        legacy_recovery_keys = legacy_keys | {
                            "executed_tickets", "protection_state"}
                        legacy_recovery_v385_keys = (
                            legacy_recovery_keys | {"executed_position_ids"})
                        protected_keys = _ORB_PROTECTED_EFFECT_KEYS
                        protected_v385_keys = _ORB_PROTECTED_EFFECT_V385_KEYS
                        ok = ok and frozenset(eff) in {
                            frozenset(legacy_keys),
                            frozenset(legacy_recovery_keys),
                            frozenset(legacy_recovery_v385_keys),
                            frozenset(protected_keys),
                            frozenset(protected_v385_keys),
                        }
                        ok = ok and eff.get("kind") == "orb_entry"
                        ok = (ok and _continuity_session(
                            eff.get("date")) is not None)
                        if frozenset(eff) in {
                                frozenset(legacy_recovery_keys),
                                frozenset(legacy_recovery_v385_keys),
                                frozenset(protected_keys),
                                frozenset(protected_v385_keys)}:
                            ok = (ok and eff.get("protection_state") in {
                                      "EXPECTED", "FLATTEN_REQUIRED"}
                                  and isinstance(
                                      eff.get("executed_tickets"), list))
                            tickets = eff.get("executed_tickets", [])
                            if (not all(isinstance(ticket, int)
                                        and not isinstance(ticket, bool)
                                        and 0 < ticket <= _MAX_MT5_TICKET
                                        for ticket in tickets)
                                    or len(tickets) != len(set(tickets))):
                                ok = False
                        if "executed_position_ids" in eff:
                            identifiers = eff.get("executed_position_ids")
                            ok = (ok and isinstance(identifiers, list)
                                  and all(isinstance(identifier, int)
                                          and not isinstance(identifier, bool)
                                          and 0 < identifier <= _MAX_MT5_TICKET
                                          for identifier in identifiers)
                                  and len(identifiers) == len(set(identifiers)))
                        if (frozenset(eff)
                                == frozenset(protected_v385_keys)):
                            ok = (ok
                                  and _finite_num(
                                      eff.get("max_stop_loss"), positive=True)
                                  and _finite_num(
                                      eff.get("max_notional"), positive=True))
                        if frozenset(eff) in {
                                frozenset(protected_keys),
                                frozenset(protected_v385_keys)}:
                            ok = (ok
                                  and eff.get("side") == x.get("side")
                                  and _finite_num(
                                      eff.get("expected_entry"), positive=True)
                                  and _finite_num(
                                      eff.get("expected_sl"), positive=True)
                                  and _finite_num(
                                      eff.get("expected_tp"), positive=True)
                                  and _finite_num(
                                      eff.get("tolerance"), positive=True)
                                  and _finite_num(
                                      eff.get("price_tick"), positive=True)
                                  )
                            if ok:
                                entry = float(eff["expected_entry"])
                                tick_size = float(eff["price_tick"])
                                ok = (math.isclose(
                                          float(eff["tolerance"]), tick_size,
                                          rel_tol=0.0,
                                          abs_tol=max(1e-12,
                                                      abs(tick_size) * 1e-12))
                                      and tick_size <= entry * 0.001
                                      and ((eff["expected_sl"] < entry
                                            < eff["expected_tp"])
                                           if x.get("side") == "buy" else
                                           (eff["expected_tp"] < entry
                                            < eff["expected_sl"])))
            if not ok: problems.append("_order_intent malformed")
        if "_close_intent" in st:
            x = st.get("_close_intent")
            if not _valid_close_intent_authority(x):
                problems.append("_close_intent malformed")
        if "_close_only_halt" in st:
            x = st.get("_close_only_halt")
            if not _valid_close_only_halt_record(x):
                problems.append("_close_only_halt malformed")
        if "_safety_recovery_pending" in st:
            if not _valid_safety_recovery_pending(
                    st.get("_safety_recovery_pending"), st):
                problems.append(
                    "_safety_recovery_pending malformed/conflicting")
        if "_ledger_recovery_halt" in st:
            if not _valid_ledger_recovery_halt(
                    st.get("_ledger_recovery_halt")):
                problems.append("_ledger_recovery_halt malformed")
        if "_v389_takeover_ledger_bridge" in st:
            if not _valid_v389_takeover_ledger_bridge(
                    st.get("_v389_takeover_ledger_bridge"), st):
                problems.append(
                    "_v389_takeover_ledger_bridge malformed/conflicting")
        if "_ledger_bootstrap" in st:
            if not _valid_ledger_bootstrap(st.get("_ledger_bootstrap"), st):
                problems.append("_ledger_bootstrap malformed/conflicting")
        if "_target_flat_watch" in st:
            x = st.get("_target_flat_watch")
            ok = _valid_target_watch(x, st)
            if not ok: problems.append("_target_flat_watch malformed")
        if "_target_hit" in st:
            x = st.get("_target_hit")
            if not _valid_target_hit(x, st):
                problems.append("_target_hit malformed/conflicting")
        if "_post_hit_catchup" in st:
            if not _valid_post_hit_catchup(
                    st.get("_post_hit_catchup"), st):
                problems.append("_post_hit_catchup malformed/conflicting")
        if "_continuity_export_txn" in st:
            if not _valid_continuity_export_txn(
                    st.get("_continuity_export_txn"), st):
                problems.append("_continuity_export_txn malformed/conflicting")
        dc = st.get("_daycount")
        if isinstance(dc, dict) and "pending" in dc:
            if (not _valid_day_roll_txn(dc.get("pending"), dc)
                    and not ledger_quarantine_ok):
                problems.append("_daycount.pending malformed/conflicting")
        if isinstance(dc, dict) and "next_interval_candidate" in dc:
            if (not _valid_next_interval_candidate(
                    dc.get("next_interval_candidate"), dc)
                    and not ledger_quarantine_ok):
                problems.append(
                    "_daycount.next_interval_candidate malformed/conflicting")
        if isinstance(dc, dict) and "next_interval_dip" in dc:
            if (not _valid_next_interval_dip(
                    dc.get("next_interval_dip"), dc)
                    and not ledger_quarantine_ok):
                problems.append(
                    "_daycount.next_interval_dip malformed/conflicting")
        sh = st.get("shadow")
        if isinstance(sh, dict) and "finality_txn" in sh:
            if (not _valid_finality_txn(sh.get("finality_txn"), sh)
                    and not ledger_quarantine_ok):
                problems.append("shadow.finality_txn malformed/conflicting")
    _SAFETY_STATE_INVALID[0] = bool(problems)
    if problems and log_bad:
        _log_throttled("*** DURABLE SAFETY RECORD INVALID ("
                       + "; ".join(problems)
                       + ") — fail-closed/manual recovery; rails remain live",
                       key="invalid safety record", window=300)
    return not problems


def _validate_safety_records(
        st, log_bad=False, allow_target_ledger_quarantine=False,
        allow_target_missing_handoff=False):
    """Total fail-closed boundary for arbitrary durable JSON trees."""
    try:
        return bool(_validate_safety_records_impl(
            st, log_bad=log_bad,
            allow_target_ledger_quarantine=allow_target_ledger_quarantine,
            allow_target_missing_handoff=allow_target_missing_handoff))
    except Exception as exc:
        _SAFETY_STATE_INVALID[0] = True
        if log_bad:
            try:
                _log_throttled(
                    "*** DURABLE SAFETY RECORD VALIDATION FAILED ("
                    + type(exc).__name__
                    + ") — fail-closed/manual recovery; rails remain live",
                    key="invalid safety record", window=300)
            except Exception:
                pass
        return False


def _anchor_increase_authorized(st):
    """Return True only for V386's current-day proved-anchor full-risk state.

    A realized-only reconstruction is useful for conservative loss rails, but
    is never entry authority.  The saved proof must also match a fresh,
    identity-qualified broker Prague-day witness; yesterday's structurally
    valid proof cannot authorize a post-midnight increase before day roll.
    Flat accounts wait and owned positions can retain/reduce without any
    cold-session sizing multiplier.
    """
    if not isinstance(st, dict):
        return False
    binding = st.get("_lifecycle_binding")
    br = st.get("breaker")
    if not (
            _valid_current_lifecycle_binding(binding)
            and binding.get("anchor_risk_policy") == _ANCHOR_RISK_POLICY
            and isinstance(br, dict)
            and br.get("cold_start") is False
            and _valid_prague_anchor_proof(br.get("anchor_proof"), st)):
        return False
    rail_now = _broker_prague_rail_now(
        allow_scheduled_maintenance=True)
    return bool(
        rail_now is not None
        and br.get("date") == rail_now.date().isoformat())


def _new_risk_blocked():
    st = _RUNTIME_STATE[0]
    safety_ok = _validate_safety_records(st, log_bad=True)
    gate_start_ok = _validate_gate_start_authority(st, log_bad=True)
    pending = isinstance(st, dict) and "_order_intent" in st
    close_pending = isinstance(st, dict) and "_close_intent" in st
    close_only = isinstance(st, dict) and "_close_only_halt" in st
    recovery_record = (st.get("_safety_recovery_pending")
                       if isinstance(st, dict) else None)
    safety_recovery_pending = bool(
        isinstance(st, dict) and "_safety_recovery_pending" in st
        and not (isinstance(recovery_record, dict)
                 and recovery_record.get("status") == "COMMITTED"))
    ledger_recovery = (isinstance(st, dict)
                       and "_ledger_recovery_halt" in st)
    target_watch = isinstance(st, dict) and "_target_flat_watch" in st
    target_hit = isinstance(st, dict) and "_target_hit" in st
    continuity_export_pending = (isinstance(st, dict)
                                 and "_continuity_export_txn" in st)
    takeover = (st.get("_predecessor_takeover")
                if isinstance(st, dict) else None)
    takeover_scale = (st.get("_takeover_applied_scale")
                      if isinstance(st, dict) else None)
    v388_incident_new_risk_hold = bool(
        _V388_OBSERVATION_SAFE_DOWN_ONLY)
    takeover_pending = bool(
        isinstance(takeover, dict)
        and (takeover.get("stage") != "COMMITTED"
             or takeover.get("status") != "COMMITTED"
             or takeover.get("anchor_status") != "PROVED"
             or not _takeover_release_pair_proved(st)
             or (_takeover_applied_scale_required(st)
                 and (not _valid_takeover_applied_scale(
                      takeover_scale, st)
                      or takeover_scale.get("status") != "APPLIED"))))
    dc = st.get("_daycount") if isinstance(st, dict) else None
    day_roll_pending = isinstance(dc, dict) and "pending" in dc
    next_interval_pending = (
        isinstance(dc, dict)
        and ("next_interval_candidate" in dc
             or "next_interval_dip" in dc))
    clock_hold_dip = isinstance(st, dict) and "_clock_hold_dip" in st
    sh = st.get("shadow") if isinstance(st, dict) else None
    finality_pending = isinstance(sh, dict) and "finality_txn" in sh
    reopen_guard = _active_reopen_entry_guard()
    unleased_reopen = (isinstance(st, dict)
                       and "_unleased_reopen_guard" in st)
    anchor_unproved = not _anchor_increase_authorized(st)
    r4_record = st.get("_r4_migration") if isinstance(st, dict) else None
    r4_migration_pending = bool(
        ("_r4_migration" in st
         and (not isinstance(r4_record, dict)
              or r4_record.get("stage") != "COMMITTED"))
        if isinstance(st, dict) else False)
    r4_predecessor_lifecycle = bool(
        isinstance(st, dict)
        and _valid_v389_lifecycle_binding(st.get("_lifecycle_binding")))
    operator_paused = isinstance(st, dict) and "_pause_new_risk" in st
    return bool(_SAVE_FAILED[0] or _HEALTH_BAD[0]
                or operator_paused
                or r4_migration_pending or r4_predecessor_lifecycle
                or _EXTERNAL_CASHFLOW_UNKNOWN[0]
                or ((LIVE or EXPORT_CONTINUITY)
                    and not _UTC_EPOCH_QUALIFIED[0])
                or _SYMBOLS_BAD[0]
                or _POSITIONS_UNKNOWN[0] or pending or close_pending
                or close_only or safety_recovery_pending or ledger_recovery
                or target_watch or target_hit or continuity_export_pending
                or takeover_pending
                or v388_incident_new_risk_hold
                or day_roll_pending or next_interval_pending
                or clock_hold_dip
                or _ORDERS_UNKNOWN[0]
                or _ACCOUNT_CONFLICT[0] or _PENDING_ORDER_CONFLICT[0]
                or _CONTINUITY_INVALID[0]
                or _ECONOMIC_INPUT_INVALID[0] or _DAILY_AUTHORITY_INVALID[0]
                or reopen_guard is not None
                or unleased_reopen
                or anchor_unproved
                or not gate_start_ok or not safety_ok)

def _nnr_causes(reason=None):
    """Truthful list of every active durable no-new-risk cause.

    Shared by the per-poll latch line and the periodic operator status
    (build order section 19: the console names the EXACT blocker).
    Presentation only — never part of trading control.
    """
    causes = []
    _st = _RUNTIME_STATE[0]
    if _SAVE_FAILED[0]: causes.append("state save failed")
    if _HEALTH_BAD[0]: causes.append(_HEALTH_REASON[0] or "time/feed unhealthy")
    if _EXTERNAL_CASHFLOW_UNKNOWN[0]:
        causes.append("external-cashflow history unproved")
    if ((LIVE or EXPORT_CONTINUITY)
            and not _UTC_EPOCH_QUALIFIED[0]):
        causes.append("broker epoch frame not automatically qualified")
    if _POSITIONS_UNKNOWN[0]: causes.append("positions inventory unreadable")
    if _ORDERS_UNKNOWN[0]: causes.append("pending-order inventory unreadable")
    if _ACCOUNT_CONFLICT[0]: causes.append("foreign/wrong-symbol position present")
    if _PENDING_ORDER_CONFLICT[0]: causes.append("broker pending order present")
    if _SAFETY_STATE_INVALID[0]: causes.append("corrupt durable safety record")
    if _CONTINUITY_INVALID[0]: causes.append("invalid continuity artifact")
    if _ECONOMIC_INPUT_INVALID[0]: causes.append("invalid economic seed authority")
    if _GATE_START_INVALID[0]: causes.append("invalid challenge start authority")
    if _DAILY_AUTHORITY_INVALID[0]: causes.append("unproved daily price authority")
    if _SYMBOLS_BAD[0]: causes.append("required symbol selection unavailable")
    if not _anchor_increase_authorized(_st):
        causes.append(
            "Prague daily anchor unproved; positions retained, increases blocked")
    if _active_reopen_entry_guard() is not None:
        causes.append("durable post-reopen quote cooldown")
    if isinstance(_st, dict) and isinstance(_st.get("_order_intent"), dict):
        causes.append("unresolved order intent")
    if isinstance(_st, dict) and isinstance(_st.get("_close_intent"), dict):
        _records = _close_intent_records(_st)
        _count = "?" if _records is None else len(_records)
        causes.append(f"{_count} unresolved exact-ticket close intent(s)")
    if isinstance(_st, dict) and isinstance(_st.get("_close_only_halt"), dict):
        causes.append("persistent close-only halt")
    if isinstance(_st, dict) and "_pause_new_risk" in _st:
        causes.append("operator pause (--resume-paused to clear)")
    if (isinstance(_st, dict)
            and _valid_v389_lifecycle_binding(
                _st.get("_lifecycle_binding"))):
        causes.append("r4 predecessor lifecycle awaiting one-time "
                      "migration")
    _r4rec = _st.get("_r4_migration") if isinstance(_st, dict) else None
    if (isinstance(_st, dict) and "_r4_migration" in _st
            and (not isinstance(_r4rec, dict)
                 or _r4rec.get("stage") != "COMMITTED")):
        causes.append("one-time r4 migration incomplete")
    _recovery_record = (_st.get("_safety_recovery_pending")
                        if isinstance(_st, dict) else None)
    if (isinstance(_st, dict)
            and "_safety_recovery_pending" in _st
            and not (isinstance(_recovery_record, dict)
                     and _recovery_record.get("status") == "COMMITTED")):
        causes.append("incomplete V383 safety-recovery transaction")
    if (isinstance(_st, dict)
            and isinstance(_st.get("_ledger_recovery_halt"), dict)):
        causes.append("multi-session ledger recovery halt")
    if isinstance(_st, dict) and isinstance(_st.get("_target_flat_watch"), dict):
        causes.append("target late-fill watch")
    if isinstance(_st, dict) and isinstance(_st.get("_target_hit"), dict):
        causes.append("permanent TARGET HIT phase lock")
    if (isinstance(_st, dict)
            and isinstance(_st.get("_continuity_export_txn"), dict)):
        causes.append("continuity export settlement pending")
    _takeover = (_st.get("_predecessor_takeover")
                 if isinstance(_st, dict) else None)
    if isinstance(_takeover, dict):
        if _takeover.get("status") == "MANUAL_REVIEW":
            causes.append("V383/V385 takeover manual review required")
        elif _takeover.get("stage") != "COMMITTED":
            causes.append(
                "predecessor takeover "
                + str(_takeover.get("stage", "unproved")).lower())
    if _V388_OBSERVATION_SAFE_DOWN_ONLY:
        causes.append(
            "V388 incident is observation/safe-down only; MT5 has no "
            "atomic account+inventory authority token")
    if (isinstance(_st, dict)
            and isinstance(_st.get("_daycount"), dict)
            and isinstance(_st["_daycount"].get("pending"), dict)):
        causes.append("unresolved account day-roll finality")
    if (isinstance(_st, dict)
            and isinstance(_st.get("_daycount"), dict)
            and isinstance(_st["_daycount"].get(
                "next_interval_candidate"), dict)):
        causes.append("queued Friday NY17 account mark")
    if isinstance(_st, dict) and "_clock_hold_dip" in _st:
        causes.append("unmerged clock-hold dip observation")
    if isinstance(_st, dict) and "_unleased_reopen_guard" in _st:
        causes.append("unleased closed-start reopen stabilization")
    if not causes and reason is not None:
        # Some fail-closed send guards (invalid contract metadata, crossed
        # tick, off-grid lot) are intentionally local/transient rather than
        # durable global latches.  Still report the actual guard reason;
        # never an empty cause list for an active latch.
        causes.append(str(reason))
    return causes


def _nnr_block(reason):
    """v3.7.12 (P1b): an exposure-INCREASING order path hit while the latch is
    set — skip it with ONE loud line per poll (exempt from _log_throttled by
    design: the operator must see it every poll)."""
    if not _NNR_POLL[0]:
        _NNR_POLL[0] = True
        causes = _nnr_causes(reason)
        _console_note_wait(
            "no-new-risk latch active: " + ("; ".join(causes) or str(reason)))
        log(f"[WARN] NO-NEW-RISK latch ACTIVE ({'; '.join(causes)}) — skipping "
            f"new/increased exposure ({reason}); reductions, closes, rails "
            f"and reconciliation continue; each latch clears only on its "
            f"own verified recovery")

def save_state(st):
    """v3.7.12 (P1): NEVER raises — persistence must never precede rails
    (CO-1: a full disk used to crash the save, and under the watchdog the
    bot died pre-rails while positions rode). Returns True on success.
    A failure SETS the no-new-risk latch; the next success CLEARS it."""
    tmp = STATE_FILE + ".tmp"
    private_tmp = None
    try:
        if not isinstance(st, dict) or not _strict_json_value(st):
            raise TypeError("state contains a non-JSON or non-finite value")
        if _STATE_IMAGE_KEY in st:
            raise ValueError("reserved state-image envelope in runtime state")
        image = copy.deepcopy(st)
        # Preserve tiny synthetic unit-test dictionaries byte-semantically, but
        # every real lifecycle image receives a monotonic generation/digest.
        # Legacy production state is upgraded on its first successful save.
        if "_lifecycle_binding" in image:
            generations = [_STATE_GENERATION[0]]
            for path in (STATE_FILE, tmp, STATE_FILE + ".bak"):
                current = _read_state_image(path)
                if current is not None:
                    generations.append(current["generation"])
            generation = max(generations) + 1
            if generation > 9_007_199_254_740_991:
                raise OverflowError("state generation exhausted")
            digest = _state_body_digest(image)
            if digest is None:
                raise ValueError("state body is not canonical finite JSON")
            image[_STATE_IMAGE_KEY] = {
                "schema": _STATE_IMAGE_SCHEMA,
                "generation": generation,
                "sha256": digest,
            }
        else:
            generation = _STATE_GENERATION[0]
        # Never open the public crash-temp name for writing: a crash-left symlink
        # there would redirect the state bytes to an arbitrary target.  Write a
        # kernel-created exclusive sibling, flush it, then atomically replace the
        # public name (os.replace replaces a symlink itself; it does not follow
        # the link).  Only the canonical .tmp participates in crash recovery.
        parent = os.path.dirname(STATE_FILE) or "."
        prefix = os.path.basename(STATE_FILE) + ".write-"
        fd, private_tmp = tempfile.mkstemp(prefix=prefix, dir=parent)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(image, f, indent=1, ensure_ascii=False, allow_nan=False)
            f.flush(); os.fsync(f.fileno())
        os.replace(private_tmp, tmp)
        private_tmp = None
        if os.path.exists(STATE_FILE):
            # A failed rotation is a failed save.  Keep the flushed temp as
            # crash-recovery evidence and latch NNR instead of overwriting the
            # only current primary while silently retaining a stale backup.
            os.replace(STATE_FILE, STATE_FILE + ".bak")
        os.replace(tmp, STATE_FILE)
        _STATE_GENERATION[0] = max(_STATE_GENERATION[0], generation)
        if _SAVE_FAILED[0]:
            _SAVE_FAILED[0] = False
            log("*** state save SUCCEEDED — persistence restored; "
                "persistence NO-NEW-RISK cause CLEARED")
        return True
    except Exception as e:
        if isinstance(private_tmp, str):
            try:
                if os.path.isfile(private_tmp) and not os.path.islink(private_tmp):
                    os.unlink(private_tmp)
            except Exception:
                pass
        _SAVE_FAILED[0] = True
        log(f"[WARN] STATE SAVE FAILED ({e!r}) — NO-NEW-RISK latch SET: "
            f"managing existing positions only until a save succeeds")
        return False

# ============================================================ CONTROLLER
def cushion_mult(equity_ratio):
    """cushion = (eq-0.90)/0.10 ; mult = clip(cushion^ALPHA, MFLOOR, MCAP)."""
    cushion = max((equity_ratio - 0.90) / 0.10, 0.0)
    return min(max(cushion**ALPHA, MFLOOR), MCAP)

def age_boost(age_days):
    """B while age<D, linear taper to 1 over next T days, else 1."""
    D, B, T = CFG["D"], CFG["B"], CFG["T"]
    if age_days < D: return B
    if age_days < D + T: return 1 + (B - 1) * (D + T - age_days) / T
    return 1.0

def target_lock(equity_ratio):
    if TARGET is None:                  # funded: no target, no lock
        return 1.0
    gap = (1 + TARGET) - equity_ratio
    if gap < LOCK_BAND:
        return max(LOCK_FLOOR, gap / LOCK_BAND)
    return 1.0

def book_leverage(equity_ratio, book_vol20, max_dip20, age_days, pl=1.0,
                  lock_equity_ratio=None):
    """The full v12 leverage stack, numerically identical to sim11b.

    sim11b: Lb = clip(tv/vol, minL, maxL); L = Lb*mult*boost*lock;
            L = min(L, 5%/(gmult*vol), theta*brk/mlo, maxL).
    The base tv/vol is CLIPPED to [MIN_LEVERAGE, MAX_LEVERAGE] BEFORE the
    mult/boost/lock factors. `pl` (v3.3.0) is the post-loss de-lever factor
    (funded mode: 0.75 after a losing session, else 1.0) and multiplies the
    SAME product, before the guard mins — matching the funded reference sim — omitting this over-levers in low-vol drawdown
    states. book_vol20 MUST be the book's own daily vol, not raw NAS vol.
    """
    v = max(book_vol20, 0.0005)
    Lb = min(max((CFG["tv"] / 100.0) / v, MIN_LEVERAGE), MAX_LEVERAGE)  # base clip
    lock_ratio = (equity_ratio if lock_equity_ratio is None
                  else lock_equity_ratio)
    L = Lb * cushion_mult(equity_ratio) * age_boost(age_days) * target_lock(lock_ratio) * pl
    L = min(L, 0.05 / (GMULT * v))                            # daily-loss guard
    if max_dip20 and max_dip20 > 0:
        L = min(L, THETA * (BREAKER_PCT / 100.0) / max_dip20)  # dip guard
    return float(min(max(L, 0.0), MAX_LEVERAGE))              # maxL binds last

# ============================================================ MT5 HELPERS
_BOOT_IDENT = [None]   # v3.7.9 (F2): (login, server) captured at the startup
                       # banner read; the reconnect path (F3) verifies against it
_BOOT_CONTINUITY_SHA256 = [None]  # exact virgin artifact witnessed at bind
_ACTIVE_MT5_PATH = [None]  # None=single-terminal auto; str=explicit path pin
_INSTANCE_MUTEX_HANDLE = [None]
_INSTANCE_LOCK_FD = [None]


def _account_singleton_key(ai):
    """Stable non-secret key for one process authority per server/login."""
    raw = (f"{getattr(ai, 'server', None)!s}\0"
           f"{getattr(ai, 'login', None)!s}").encode("utf-8")
    return hashlib.sha256(raw).hexdigest()[:24]


def _account_mutex_name(ai):
    """Cross-Windows-session singleton name for one broker login."""
    return f"Global\\V380_ACCOUNT_{_account_singleton_key(ai)}"


def _acquire_account_singleton(ai):
    """Acquire an account-wide process lock before state or order activity.

    Windows uses a named kernel mutex, so independent folders and double
    clicks still contend on the same (server, login) authority. POSIX uses a
    nonblocking advisory lock solely as an offline/testable equivalent.
    Failure is fail-closed; the caller must refuse before any order path.
    """
    hook = globals().get("_TEST_SINGLETON_ACQUIRE")
    if hook is not None:
        return bool(hook(_account_singleton_key(ai)))
    if _INSTANCE_MUTEX_HANDLE[0] is not None or _INSTANCE_LOCK_FD[0] is not None:
        return True
    key = _account_singleton_key(ai)
    if os.name == "nt":
        try:
            import ctypes
            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            kernel32.CreateMutexW.argtypes = [ctypes.c_void_p,
                                              ctypes.c_int,
                                              ctypes.c_wchar_p]
            kernel32.CreateMutexW.restype = ctypes.c_void_p
            kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
            handle = kernel32.CreateMutexW(None, False,
                                           _account_mutex_name(ai))
            err = ctypes.get_last_error()
            if not handle:
                log(f"*** ACCOUNT SINGLETON mutex creation failed ({err}) — "
                    "refusing to run")
                return False
            if err == 183:  # ERROR_ALREADY_EXISTS
                kernel32.CloseHandle(handle)
                log("*** DUPLICATE BOT INSTANCE for this server/login — "
                    "refusing before state or orders")
                return False
            _INSTANCE_MUTEX_HANDLE[0] = (kernel32, handle)
            return True
        except Exception as exc:
            log(f"*** ACCOUNT SINGLETON mutex error ({type(exc).__name__}: "
                f"{exc}) — refusing to run")
            return False
    try:
        import fcntl
        path = os.path.join(tempfile.gettempdir(), f"v380-account-{key}.lock")
        fd = os.open(path, os.O_CREAT | os.O_RDWR, 0o600)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except (BlockingIOError, OSError):
            os.close(fd)
            log("*** DUPLICATE BOT INSTANCE for this server/login — "
                "refusing before state or orders")
            return False
        _INSTANCE_LOCK_FD[0] = fd
        return True
    except Exception as exc:
        log(f"*** ACCOUNT SINGLETON fallback error ({type(exc).__name__}: "
            f"{exc}) — refusing to run")
        return False


def _release_account_singleton():
    pair = _INSTANCE_MUTEX_HANDLE[0]
    _INSTANCE_MUTEX_HANDLE[0] = None
    if pair is not None:
        try: pair[0].CloseHandle(pair[1])
        except Exception: pass
    fd = _INSTANCE_LOCK_FD[0]
    _INSTANCE_LOCK_FD[0] = None
    if fd is not None:
        try: os.close(fd)
        except Exception: pass

def _terminal_path_ok(path):
    """Validate one literal, absolute regular terminal executable path."""
    if (not isinstance(path, str) or not path or not os.path.isabs(path)
            or os.path.basename(path).lower() != "terminal64.exe"):
        return False
    try:
        if not os.path.isfile(path) or os.path.islink(path):
            return False
        attrs = getattr(os.lstat(path), "st_file_attributes", 0)
        if attrs & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400):
            return False
    except Exception:
        return False
    return True


def _require_live_cli_contract(path=None):
    """Validate a configured path; single-terminal auto mode needs none."""
    if not (LIVE or EXPORT_CONTINUITY):
        return True
    selected = _ACTIVE_MT5_PATH[0] if path is None else path
    if selected is None and MT5_PATH is None:
        return True
    if not _terminal_path_ok(selected):
        log("*** MT5 PATH REFUSED before attach/state: DEFAULT_MT5_PATH or "
            "optional --mt5-path must name one existing literal absolute "
            "terminal64.exe; leave DEFAULT_MT5_PATH = None and omit the "
            "suffix to auto-discover the one installed MT5 terminal")
        raise SystemExit(5)
    return True


def _configured_live_identity_gate(ai, where):
    """Enforce the captured full login/server pair after first boot read."""
    if not (LIVE or EXPORT_CONTINUITY):
        return True
    _require_live_cli_contract()
    got = (getattr(ai, "login", None), getattr(ai, "server", None))
    expected = _BOOT_IDENT[0]
    if expected is not None and got != expected:
        log(f"[WARN] MT5 IDENTITY MISMATCH {where} (got login {got[0]!r} "
            f"server {got[1]!r}, expected {expected[0]!r} "
            f"{expected[1]!r}) — refusing before state/orders")
        try: mt5.shutdown()
        finally: raise SystemExit(3)
    return True


def _mt5_initialize():
    """Use auto-discovery, one editable default, or one CLI path override."""
    path = _ACTIVE_MT5_PATH[0]
    if path is None:
        # The operator explicitly chose the single-terminal V376 behavior:
        # with no suffix MetaTrader5 discovers/launches the installed terminal.
        # The one-line source default provides V376-style edit-once operation;
        # an optional final --mt5-path remains the strict higher-priority pin.
        path = MT5_PATH
        if path is None:
            return mt5.initialize()
        _require_live_cli_contract(path)
        _ACTIVE_MT5_PATH[0] = path
    _require_live_cli_contract(path)
    return mt5.initialize(path=path)

def _capture_boot_identity(ai):
    """v3.7.9 (F2): remember who we logged in as — (login, server) — for the
    session. The reconnect identity check (F3) compares against this."""
    got = (getattr(ai, "login", None), getattr(ai, "server", None))
    if (isinstance(got[0], bool) or not isinstance(got[0], int)
            or got[0] <= 0 or not isinstance(got[1], str) or not got[1]):
        log("[WARN] MT5 IDENTITY unreadable/malformed at boot — refusing")
        try: mt5.shutdown()
        finally: raise SystemExit(3)
    _BOOT_IDENT[0] = got

def _mt5_reconnect_verify():
    """v3.7.9 (F3): rebuild using the SAME startup mode as boot, then
    verify the terminal still holds the SAME account: login/server must match
    the boot identity or the bot halts (exit 3) rather than poll — and
    eventually trade — a stranger's terminal. Returns False when re-init
    failed (caller keeps today's retry behavior); True when re-init succeeded
    (identity verified, or unreadable-yet — deferred, the next reconnect
    cycle re-verifies). Extracted so the regression suite drives the shipped
    code (the _arming_clock_reset precedent)."""
    # A rebuilt IPC connection must prove its epoch frame again; a prior
    # process-local tick/D1 witness or ORB liveness sample cannot authorize a
    # new terminal link.
    # A reconnect also destroys the consecutiveness of any loaded reopen
    # stabilization proof.  Reset that durable obligation before clearing the
    # process-local epoch witness so a pre-fault sample/cooldown cannot be
    # combined with observations from the rebuilt terminal link.
    _restart_loaded_reopen_recovery("MT5 reconnect")
    _reset_broker_epoch_qualification()
    _HEALTH_BAD[0] = True
    _HEALTH_REASON[0] = "automatic broker epoch requalification pending"
    if not _mt5_initialize():
        log(f"MT5 re-initialize failed: {mt5.last_error()}")
        return False
    ai2 = mt5.account_info()
    if ai2 is None:
        log("MT5 re-initialize OK but account_info unreadable — identity "
            "verification DEFERRED; the next reconnect cycle re-verifies")
        return True
    _configured_live_identity_gate(ai2, "after reconnect")
    got = (getattr(ai2, "login", None), getattr(ai2, "server", None))
    exp = _BOOT_IDENT[0]
    if exp is not None and got != exp:
        log(f"[WARN] MT5 IDENTITY MISMATCH after reconnect (got login {got[0]!r} "
            f"server {got[1]!r}, expected {exp[0]!r} {exp[1]!r}) — halting")
        try:
            mt5.shutdown()
        finally:
            sys.exit(3)
    log("MT5 re-initialize OK (identity verified: login/server match)")
    return True

def _boot_identity_gate(st):
    """v3.7.10 (R1): the F2/F3 identity guard now SURVIVES RESTARTS. The boot
    identity (login, server) persists in the state file (st["mt5_identity"]);
    every boot compares the live terminal against it BEFORE any trading poll
    and halts (exit 3) on a mismatch — closing round-29's A2: a restart
    after an identity halt used to re-capture whichever terminal answered an
    unpinned attach and silently adopt the stranger as the new baseline.
    This identity-guarded build captures only in a genuinely fresh
    folder: neither primary/backup state nor a crash-leftover state temp may
    exist. An exact, regular, self-validating continuity artifact is the sole
    permitted companion to a virgin identity bind. Any existing state whose
    identity is missing or malformed refuses before mutation/orders; it is
    never rebound to whichever terminal happened to answer. Lifecycle-stage
    authority is bound separately before any broker mutation."""
    global EXPECTED_LOGIN, EXPECTED_SERVER
    live = _BOOT_IDENT[0]
    _BOOT_CONTINUITY_SHA256[0] = None
    if live is None:
        return                    # no capture happened (selfcheck-style paths)
    saved = st.get("mt5_identity") if isinstance(st, dict) else None
    valid_saved = (isinstance(saved, dict)
                   and set(saved) == {"login", "server"}
                   and isinstance(saved.get("login"), int)
                   and not isinstance(saved.get("login"), bool)
                   and saved.get("login", 0) > 0
                   and isinstance(saved.get("server"), str)
                   and bool(saved.get("server")))
    if valid_saved:
        exp = (saved.get("login"), saved.get("server"))
        if exp != live:
            log(f"[WARN] MT5 IDENTITY MISMATCH at boot (got login {live[0]!r} "
                f"server {live[1]!r}, expected {exp[0]!r} {exp[1]!r}) — halting")
            try:
                mt5.shutdown()
            finally:
                sys.exit(3)
        EXPECTED_LOGIN, EXPECTED_SERVER = exp
        return
    continuity_present = os.path.lexists(CONTINUITY_FILE)
    continuity_valid = not continuity_present
    if continuity_present:
        try:
            before_sha256 = _continuity_artifact_sha256(CONTINUITY_FILE)
            continuity_payload = _load_continuity(CONTINUITY_FILE)
            after_sha256 = _continuity_artifact_sha256(CONTINUITY_FILE)
            continuity_valid = bool(
                before_sha256 is not None
                and before_sha256 == after_sha256
                and isinstance(continuity_payload, dict))
            if continuity_valid:
                _BOOT_CONTINUITY_SHA256[0] = after_sha256
        except Exception:
            continuity_valid = False
    allow_fresh_capture = (
        _STATE_LOAD_STATUS[0] == "missing"
        and isinstance(st, dict) and not st
        and not os.path.exists(STATE_FILE + ".tmp")
        and not os.path.lexists(CONTINUITY_FILE + ".tmp")
        and continuity_valid)
    if (allow_fresh_capture
            and isinstance(live[0], int) and not isinstance(live[0], bool)
            and live[0] > 0 and isinstance(live[1], str) and bool(live[1])):
        st["mt5_identity"] = {"login": live[0], "server": live[1]}
        EXPECTED_LOGIN, EXPECTED_SERVER = live
        return
    log("[WARN] MT5 IDENTITY AUTHORITY MISSING/MALFORMED on a non-fresh state "
        "or continuity folder — refusing before state mutation/orders; do "
        "not delete or reset durable records")
    try:
        mt5.shutdown()
    finally:
        raise SystemExit(3)

def _poll_identity_gate(ai):
    """v3.7.11 (L3): every readable account_info in the main loop is compared
    against the boot identity — a terminal that silently re-logs into a
    DIFFERENT account mid-session (no reconnect involved, so the F3 verify
    never fires) now halts within one poll instead of trading it."""
    _configured_live_identity_gate(ai, "in-process poll")
    got = (getattr(ai, "login", None), getattr(ai, "server", None))
    exp = _BOOT_IDENT[0]
    if exp is not None and got != exp:
        log(f"[WARN] MT5 IDENTITY MISMATCH in-process (got login {got[0]!r} "
            f"server {got[1]!r}, expected {exp[0]!r} {exp[1]!r}) — halting")
        try:
            mt5.shutdown()
        finally:
            sys.exit(3)


def _lower_hex64(value):
    return (isinstance(value, str) and len(value) == 64
            and all(ch in "0123456789abcdef" for ch in value))


def _valid_lifecycle_binding_for_schema(value, schema):
    """Validate the durable direct recipe/account/capital authority."""
    keys = {
        "schema", "stage", "recipe", "login", "server",
        "direct_authority_sha256", "magic_namespace", "continuity_sha256",
        "expected_start_cents", "observed_start_cents",
        "declared_capital_cents", "sizing_cents",
        "breaker_bps", "target_bps",
    }
    policy_schema = schema in {
        _V381_IMMEDIATE_LIFECYCLE_BINDING_SCHEMA,
        _V382_LIFECYCLE_BINDING_SCHEMA,
        _V383_LIFECYCLE_BINDING_SCHEMA,
        _V384_LIFECYCLE_BINDING_SCHEMA,
        _V385_LIFECYCLE_BINDING_SCHEMA,
        _V386_LIFECYCLE_BINDING_SCHEMA,
        _V389_LIFECYCLE_BINDING_SCHEMA,
        _LIFECYCLE_BINDING_SCHEMA,
    }
    if policy_schema:
        keys.add("entry_policy")
    if schema in {
            _V385_LIFECYCLE_BINDING_SCHEMA,
            _V386_LIFECYCLE_BINDING_SCHEMA,
            _V389_LIFECYCLE_BINDING_SCHEMA,
            _LIFECYCLE_BINDING_SCHEMA}:
        keys.add("capital_policy")
    if schema in {
            _V386_LIFECYCLE_BINDING_SCHEMA,
            _V389_LIFECYCLE_BINDING_SCHEMA,
            _LIFECYCLE_BINDING_SCHEMA}:
        keys.add("anchor_risk_policy")
    if schema in {
            _LEGACY_LIFECYCLE_BINDING_SCHEMA,
            _V381_GATED_LIFECYCLE_BINDING_SCHEMA}:
        authority_sha256 = _V381_GATED_DIRECT_AUTHORITY_SHA256
        allowed_recipes = {"p1", "p2-fresh", "p2-adopt", "funded"}
    elif schema == _V381_IMMEDIATE_LIFECYCLE_BINDING_SCHEMA:
        authority_sha256 = _V381_IMMEDIATE_DIRECT_AUTHORITY_SHA256
        allowed_recipes = {"p1", "p2-standalone-immediate", "funded"}
    elif schema == _V382_LIFECYCLE_BINDING_SCHEMA:
        authority_sha256 = _V382_DIRECT_AUTHORITY_SHA256
        allowed_recipes = set(_ENTRY_POLICIES_BY_RECIPE)
    elif schema == _V383_LIFECYCLE_BINDING_SCHEMA:
        authority_sha256 = _V383_DIRECT_AUTHORITY_SHA256
        allowed_recipes = set(_ENTRY_POLICIES_BY_RECIPE)
    elif schema == _V384_LIFECYCLE_BINDING_SCHEMA:
        # Schema 7 used V384's sizing-only capital policy.  It remains
        # recognizable for protect-only startup and a narrowly safe no-capital
        # migration, but it is never accepted as V386 trading authority.
        authority_sha256 = _V384_DIRECT_AUTHORITY_SHA256
        allowed_recipes = set(_ENTRY_POLICIES_BY_RECIPE)
    elif schema == _V385_LIFECYCLE_BINDING_SCHEMA:
        authority_sha256 = _V385_DIRECT_AUTHORITY_SHA256
        allowed_recipes = set(_ENTRY_POLICIES_BY_RECIPE)
    elif schema == _V386_LIFECYCLE_BINDING_SCHEMA:
        authority_sha256 = _V386_DIRECT_AUTHORITY_SHA256
        allowed_recipes = set(_ENTRY_POLICIES_BY_RECIPE)
    elif schema == _V389_LIFECYCLE_BINDING_SCHEMA:
        authority_sha256 = _V389_R4_DIRECT_AUTHORITY_SHA256
        allowed_recipes = set(_ENTRY_POLICIES_BY_RECIPE)
    elif schema == _LIFECYCLE_BINDING_SCHEMA:
        authority_sha256 = DIRECT_RECIPE_AUTHORITY_SHA256
        allowed_recipes = set(_ENTRY_POLICIES_BY_RECIPE)
    else:
        return False
    if (not isinstance(value, dict)
            or set(value) != keys
            or value.get("schema") != schema
            or not isinstance(value.get("recipe"), str)
            or value.get("recipe") not in allowed_recipes
            or value.get("stage") != _RECIPE_STAGE.get(value.get("recipe"))
            or isinstance(value.get("login"), bool)
            or not isinstance(value.get("login"), int)
            or value.get("login", 0) <= 0
            or not isinstance(value.get("server"), str)
            or not value.get("server")
            or value.get("direct_authority_sha256") != authority_sha256
            or value.get("magic_namespace") != _MAGIC_NAMESPACE):
        return False
    if (schema in {
            _V385_LIFECYCLE_BINDING_SCHEMA,
            _V386_LIFECYCLE_BINDING_SCHEMA}
            and value.get("capital_policy") !=
                _FULL_VIRTUAL_CAPITAL_POLICY):
        return False
    if (schema in {
            _V389_LIFECYCLE_BINDING_SCHEMA,
            _LIFECYCLE_BINDING_SCHEMA}
            and value.get("capital_policy") !=
                _CAMPAIGN_BASE_CAPITAL_POLICY):
        return False
    if (schema in {
            _V386_LIFECYCLE_BINDING_SCHEMA,
            _V389_LIFECYCLE_BINDING_SCHEMA,
            _LIFECYCLE_BINDING_SCHEMA}
            and value.get("anchor_risk_policy") != _ANCHOR_RISK_POLICY):
        return False
    if policy_schema:
        policy = value.get("entry_policy")
        if schema == _V381_IMMEDIATE_LIFECYCLE_BINDING_SCHEMA:
            expected_policy = {
                "p1": IMMEDIATE_ENTRY_POLICY,
                "p2-standalone-immediate": IMMEDIATE_ENTRY_POLICY,
                "funded": FUNDED_ENTRY_POLICY,
            }.get(value.get("recipe"))
            if policy != expected_policy:
                return False
        elif policy not in _ENTRY_POLICIES_BY_RECIPE.get(
                value.get("recipe"), frozenset()):
            return False
    observed = value.get("observed_start_cents")
    declared = value.get("declared_capital_cents")
    sizing = value.get("sizing_cents")
    expected = value.get("expected_start_cents")
    declared_valid = bool(
        declared is None
        or (not isinstance(declared, bool)
            and isinstance(declared, int)
            and declared > 0))
    observed_valid = bool(
        not isinstance(observed, bool)
        and isinstance(observed, int)
        and observed > 0)
    if schema in {_V385_LIFECYCLE_BINDING_SCHEMA,
                  _V386_LIFECYCLE_BINDING_SCHEMA}:
        # The translated hard floor is S - 10%*V.  A non-positive floor has
        # no meaningful account-preservation boundary, so full-virtual
        # lifecycle authorities reject it using integer cents.
        declared_within_policy = bool(
            declared is None
            or (observed_valid
                and observed * 10_000 - declared * 1_000 > 0))
    elif schema in {_V389_LIFECYCLE_BINDING_SCHEMA,
                    _LIFECYCLE_BINDING_SCHEMA}:
        # The declaration is the literal campaign base.  Its fixed 90%
        # hard floor is independent of the balance observed at attachment.
        declared_within_policy = bool(
            declared_valid
            and (declared is None or declared * 9_000 // 10_000 > 0))
    else:
        # Every predecessor used sizing-only capital and capped it at observed
        # cash.  Preserve that historical validation exactly; recognizing an
        # old record must not reinterpret its economics.
        declared_within_policy = bool(
            declared is None
            or (observed_valid and declared_valid
                and declared <= observed))
    if (not observed_valid
            or not declared_valid
            or not declared_within_policy
            or isinstance(sizing, bool) or not isinstance(sizing, int)
            or sizing <= 0
            or sizing != (declared if declared is not None else observed)):
        return False
    recipe = value["recipe"]
    if recipe == "p2-standalone-immediate":
        if schema in {
                _V384_LIFECYCLE_BINDING_SCHEMA,
                _V385_LIFECYCLE_BINDING_SCHEMA,
                _V386_LIFECYCLE_BINDING_SCHEMA,
                _V389_LIFECYCLE_BINDING_SCHEMA,
                _LIFECYCLE_BINDING_SCHEMA}:
            if expected is not None:
                return False
        elif (isinstance(expected, bool) or not isinstance(expected, int)
                or expected != _V383_P2_STANDALONE_EXPECTED_CENTS
                or observed != _V383_P2_STANDALONE_EXPECTED_CENTS):
            return False
    elif recipe in {"p2-adopt", "funded"}:
        if (isinstance(expected, bool) or not isinstance(expected, int)
                or expected <= 0 or abs(expected - observed) > 100):
            return False
    elif expected is not None:
        return False
    if recipe == "funded" and declared is not None:
        return False
    rules = {
        "p1": (350, 1000),
        "p2-fresh": (350, 500),
        "p2-adopt": (350, 500),
        "p2-standalone-immediate": (350, 500),
        "funded": (300, None),
    }
    breaker_bps = value.get("breaker_bps")
    target_bps = value.get("target_bps")
    if (isinstance(breaker_bps, bool)
            or not isinstance(breaker_bps, int)
            or breaker_bps <= 0
            or (target_bps is not None
                and (isinstance(target_bps, bool)
                     or not isinstance(target_bps, int)
                     or target_bps <= 0))
            or (breaker_bps, target_bps) != rules[recipe]):
        return False
    continuity_sha = value.get("continuity_sha256")
    if recipe in {"p1", "p2-adopt", "p2-standalone-immediate"}:
        return continuity_sha is None
    return _lower_hex64(continuity_sha)


def _valid_current_lifecycle_binding(value):
    """STRICT: the current /11 binding only — live trading authority."""
    return _valid_lifecycle_binding_for_schema(
        value, _LIFECYCLE_BINDING_SCHEMA)


