class _SeedV2Error(RuntimeError):
    pass


def _seed_require(condition, message):
    if not condition:
        raise _SeedV2Error(message)


def _seed_reject_constant(value):
    raise _SeedV2Error(f"non-finite JSON constant {value!r}")


def _seed_load_raw(path, expected_hash, expected_bytes):
    with open(path, "rb") as f:
        raw = f.read()
    _seed_require(len(raw) == expected_bytes,
                  f"{os.path.basename(path)} byte length mismatch")
    _seed_require(hashlib.sha256(raw).hexdigest() == expected_hash,
                  f"{os.path.basename(path)} SHA-256 mismatch")
    try:
        value = json.loads(raw.decode("utf-8"),
                           parse_constant=_seed_reject_constant)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise _SeedV2Error(f"invalid {os.path.basename(path)}: {exc}") from exc
    _seed_require(isinstance(value, dict),
                  f"{os.path.basename(path)} must be an object")
    return value


def _seed_finite(value, label):
    _seed_require(isinstance(value, (int, float)) and not isinstance(value, bool),
                  f"{label} must be numeric")
    result = float(value)
    _seed_require(math.isfinite(result), f"{label} must be finite")
    return result


def _seed_iso(value, label):
    _seed_require(isinstance(value, str), f"{label} must be a date string")
    try:
        parsed = date.fromisoformat(value)
    except ValueError as exc:
        raise _SeedV2Error(f"{label} is not an ISO date") from exc
    _seed_require(parsed.isoformat() == value, f"{label} is not canonical")
    return value


